type PersonaSeed = {
  id: string;
  name: string;
  nameEn: string;
  group: string;
  groupEn: string;
  def: string;
  defEn: string;
  ontologyLevel?: 1 | 2 | 3 | 4 | 5;
  eras?: PersonaEra[];
  risk?: 'clean' | 'medium' | 'high';
  tags?: string[];
  styleTags?: string[];
  controls?: string[];
  forbids?: string[];
  absorptionRule?: string;
  absorptionRuleEn?: string;
  eraMode?: PersonaTerm['eraMode'];
  realityTags?: string[];
  categoryFit?: PersonaTerm['categoryFit'];
};

const gothicEras: PersonaEra[] = ['feudal', 'early_modern', 'industrial', 'modern', 'contemporary', 'mythic'];
const modernEras: PersonaEra[] = ['modern', 'contemporary'];
const ancientEras: PersonaEra[] = ['slave', 'feudal', 'mythic'];
const futureEras: PersonaEra[] = ['near_future', 'far_future'];
const baseControls = ['body', 'costume', 'decay', 'prop', 'symbol', 'pose', 'death_mark', 'face', 'material'];
const defaultForbids = ['纯生物朋克感染化', '无解释机械义体化', '脱离死亡或诅咒证据', '把死亡主题写成普通哥特穿搭'];

const undeadFit = (group: string): PersonaCategoryFit => {
  if (group.startsWith('A.')) return personaFit('weak', {
    strong: ['dark_fantasy', 'horror', 'court'],
    usable: ['romance', 'historical', 'boudoir_aesthetic'],
    fusion: ['urban_life', 'noir_crime'],
    weak: ['science_fiction', 'cyberpunk', 'workplace']
  });
  if (group.startsWith('B.')) return personaFit('weak', {
    strong: ['horror', 'body_horror', 'post_apocalyptic'],
    usable: ['wasteland', 'war_military', 'urban_life'],
    fusion: ['dark_fantasy', 'romance'],
    weak: ['court', 'fashion_idol', 'xianxia']
  });
  if (group.startsWith('C.')) return personaFit('weak', {
    strong: ['horror', 'surreal', 'dark_fantasy'],
    usable: ['romance', 'urban_life', 'noir_crime'],
    fusion: ['science_fiction', 'cyberpunk'],
    weak: ['war_military', 'workplace', 'wasteland']
  });
  if (group.startsWith('D.')) return personaFit('weak', {
    strong: ['dark_fantasy', 'war_military', 'mythic_epic'],
    usable: ['historical', 'court', 'fantasy'],
    fusion: ['wuxia', 'xianxia'],
    weak: ['urban_life', 'fashion_idol', 'workplace']
  });
  if (group.startsWith('E.')) return personaFit('weak', {
    strong: ['dark_fantasy', 'court', 'historical'],
    usable: ['horror', 'romance', 'mythic_epic'],
    fusion: ['boudoir_aesthetic', 'surreal'],
    weak: ['science_fiction', 'cyberpunk', 'workplace']
  });
  if (group.startsWith('F.')) return personaFit('weak', {
    strong: ['historical', 'mythic_epic', 'dark_fantasy'],
    usable: ['adventure', 'horror', 'religious_ritual'],
    fusion: ['science_fiction', 'surreal'],
    weak: ['urban_life', 'fashion_idol', 'workplace']
  });
  if (group.startsWith('G.')) return personaFit('weak', {
    strong: ['dark_fantasy', 'fantasy', 'horror'],
    usable: ['religious_ritual', 'mythic_epic', 'body_horror'],
    fusion: ['xianxia', 'surreal'],
    weak: ['urban_life', 'romance', 'workplace']
  });
  if (group.startsWith('H.')) return personaFit('weak', {
    strong: ['horror', 'urban_life', 'dark_fantasy'],
    usable: ['court', 'romance', 'historical'],
    fusion: ['surreal'],
    weak: ['science_fiction', 'war_military', 'wasteland']
  });
  if (group.startsWith('I.')) return personaFit('weak', {
    strong: ['urban_life', 'horror', 'surreal'],
    usable: ['science_fiction', 'cyberpunk', 'noir_crime'],
    fusion: ['posthuman', 'romance'],
    weak: ['wuxia', 'court', 'historical']
  });
  return personaFit('weak', {
    strong: ['surreal', 'dark_fantasy', 'horror'],
    usable: ['romance', 'urban_life', 'court'],
    fusion: ['xianxia', 'fantasy'],
    weak: ['science_fiction', 'war_military', 'workplace']
  });
};

