const up = (seed: PersonaSeed): PersonaTerm => {
  const ontologyLevel = seed.ontologyLevel ?? 4;
  const eras = cleanPersonaEras(seed.eras ?? gothicEras);
  const risk = seed.risk ?? (ontologyLevel >= 4 ? 'medium' : 'clean');
  const controls = Array.from(new Set([...baseControls, ...(seed.controls || [])]));
  const eraMode = personaEraModeFor(eras, seed.eraMode);
  return {
    id: `cd_persona_undead_cursed_${seed.id}`,
    name: seed.name,
    nameEn: seed.nameEn,
    group: seed.group,
    groupEn: seed.groupEn,
    def: seed.def,
    defEn: seed.defEn,
    personaCategory: '血族 / 亡灵 / 诅咒不死人设',
    personaCategoryEn: 'Vampire / Undead / Cursed Immortal Persona',
    personaSubgroup: seed.group.replace(/^[A-J]\.\s*/, ''),
    personaSubgroupEn: seed.groupEn.replace(/^[A-J]\.\s*/, ''),
    personaKind: seed.name,
    personaKindEn: seed.nameEn,
    personaStrength: ontologyLevel >= 4 ? 'strong' : ontologyLevel >= 2 ? 'medium' : 'light',
    isCompoundPersona: true,
    ontologyLevel,
    eraMode,
    eras,
    risk,
    affects: controls,
    controls,
    forbids: Array.from(new Set([...(seed.forbids || []), ...defaultForbids])),
    absorptionRule: seed.absorptionRule || `外来元素优先折译为“${seed.name}”的死亡状态、血统符号、丧葬服制、诅咒道具、身体腐败或不死社会位置，不要把它变成普通奇幻怪物或单纯恐怖场景。`,
    absorptionRuleEn: seed.absorptionRuleEn || `Translate outside elements into the death state, bloodline symbol, mourning costume, cursed prop, bodily decay, or undead social position of "${seed.nameEn}"; do not turn it into a generic fantasy monster or plain horror scene.`,
    tags: Array.from(new Set(['persona', 'undead', 'curse', 'compound_persona', ...(seed.tags || [])])),
    realityTags: seed.realityTags || personaRealityTagsFor(ontologyLevel, ['undead', 'curse']),
    categoryFit: seed.categoryFit || undeadFitOverrides[seed.id] || undeadFit(seed.group),
    styleTags: Array.from(new Set(['undead', 'gothic', ...(seed.styleTags || []), ...(seed.tags || [])])),
    timeTags: eras
  };
};

const seeds: PersonaSeed[] = [
  { id: 'vampire_aristocrat', name: '吸血鬼贵族', nameEn: 'Vampire Aristocrat', group: 'A. 血族 / 吸血鬼阶层', groupEn: 'A. Bloodline / Vampire Class', def: '第一识别是把捕食欲望训练成上流礼仪的吸血鬼贵族。造型入口：苍白皮肤、暗红内衬、旧钱剪裁、过长手指和像邀请又像审判的侧身姿态。母题：血液被阶层制度化。张力：危险不能靠张牙舞爪，而要藏在脖颈距离、杯中暗红和过度克制的礼貌里。视觉证据：祖传戒指、天鹅绒礼服、细犬般的脸部线条、无声靠近的站姿。边界：避免普通哥特王子或血腥怪物。', defEn: 'First read: a vampire aristocrat who has trained predation into upper-class etiquette. Styling entry: pallor, dark-red lining, old-money tailoring, too-long fingers, and a side pose that feels both invitation and judgment. Motif: blood institutionalized by class. Tension: danger should not come from snarling, but from neck distance, a dark-red glass, and excessively controlled courtesy. Visual evidence: inherited ring, velvet formalwear, hound-like facial line, and a silent approaching stance. Boundary: avoid a generic goth prince or gore monster.', tags: ['vampire', 'aristocrat', 'old_money'] },
  { id: 'vampire_debutante', name: '吸血鬼社交季少女', nameEn: 'Vampire Debutante', group: 'A. 血族 / 吸血鬼阶层', groupEn: 'A. Bloodline / Vampire Class', def: '第一识别是第一次被血族社交场展示的年轻贵族身体。造型入口：白手套、初次舞会礼服、细尖犬齿和被训练出的温顺微笑。母题：捕食者进入婚配市场。张力：她看似被保护，眼神却比监护人更清楚餐桌规则。视觉证据：颈链、舞会号码牌、微微发冷的指尖、压住饥饿的站姿。边界：避免普通校园吸血鬼或甜美公主。', defEn: 'First read: a young noble body displayed for the first time in vampire society. Styling entry: white gloves, debutante gown, small fangs, and a trained obedient smile. Motif: a predator entering the marriage market. Tension: she seems protected, yet her eyes understand the table rules better than her guardians. Visual evidence: choker, ball card, cold fingertips, and a posture suppressing hunger. Boundary: avoid a generic school vampire or sweet princess.', tags: ['vampire', 'debutante', 'ball'] },
  { id: 'blood_bank_doctor', name: '血库医生', nameEn: 'Blood-Bank Doctor', group: 'A. 血族 / 吸血鬼阶层', groupEn: 'A. Bloodline / Vampire Class', def: '第一识别是把吸血欲望伪装成医疗秩序的血库医生。造型入口：白大褂、冷藏箱标签、橡胶手套、精确抽血姿态和不该太温柔的病床距离。母题：现代机构替古老捕食提供合法接口。张力：他看似救治身体，实则用流程、编号和温控管理血液。视觉证据：血袋、扫码标签、苍白口罩边缘、洁净而危险的手。边界：避免普通医生或血腥屠夫。', defEn: 'First read: a blood-bank doctor who disguises vampiric hunger as medical order. Styling entry: lab coat, cold-storage labels, rubber gloves, precise blood-draw posture, and a bedside distance that should not feel so gentle. Motif: modern institution giving ancient predation a legal interface. Tension: he appears to treat bodies while managing blood through process, numbers, and temperature. Visual evidence: blood bags, barcode labels, pale mask edge, and clean dangerous hands. Boundary: avoid a generic doctor or gore butcher.', ontologyLevel: 3, eras: modernEras, tags: ['vampire', 'doctor', 'blood_bank'] },
  { id: 'nightclub_vampire_owner', name: '夜店血族老板', nameEn: 'Nightclub Vampire Owner', group: 'A. 血族 / 吸血鬼阶层', groupEn: 'A. Bloodline / Vampire Class', def: '第一识别是把夜店经营成狩猎场的血族老板。造型入口：黑衬衫、暗红灯光、VIP手环、酒杯和在喧闹里保持过度安静的脸。母题：夜生活成为血族阶层的现代领地。张力：他不需要亲自扑咬，空间、保安和音乐节奏已经替他筛选猎物。视觉证据：后台钥匙、卡座阴影、过亮犬齿反光、慢到不合拍的手势。边界：避免普通夜店老板或廉价吸血鬼cos。', defEn: 'First read: a vampire owner who runs a nightclub as a hunting ground. Styling entry: black shirt, dark-red light, VIP wristbands, glassware, and a face too quiet inside noise. Motif: nightlife as modern vampire territory. Tension: he need not attack; space, security, and music already filter prey for him. Visual evidence: backstage keys, booth shadow, fang glint, and gestures slower than the beat. Boundary: avoid a generic club owner or cheap vampire cosplay.', eras: modernEras, tags: ['vampire', 'nightclub', 'owner'] },
  { id: 'vampire_school_prince', name: '吸血鬼学院王子', nameEn: 'Vampire School Prince', group: 'A. 血族 / 吸血鬼阶层', groupEn: 'A. Bloodline / Vampire Class', def: '第一识别是被学院制服和血统传闻共同供起来的吸血鬼王子。造型入口：深色校服、家徽领针、苍白脖颈、安静书本和从不过界的凝视。母题：青春秩序里的古老阶层。张力：他看似校园中心，却像被一套比学校更老的规则隔开。视觉证据：整洁领口、旧式戒指、晚间走廊、被同学让开的距离。边界：避免普通校草或恋爱轻小说模板。', defEn: 'First read: a vampire prince elevated by academy uniform and bloodline rumor. Styling entry: dark school uniform, house pin, pale neck, quiet books, and a gaze that never crosses the line. Motif: ancient class inside youth order. Tension: he seems central to school life yet separated by rules older than the school. Visual evidence: neat collar, old ring, night corridor, and classmates giving him distance. Boundary: avoid a generic school heartthrob or romance-light-novel template.', eras: modernEras, tags: ['vampire', 'school', 'prince'] },
  { id: 'old_blood_countess', name: '古血女伯爵', nameEn: 'Old-Blood Countess', group: 'A. 血族 / 吸血鬼阶层', groupEn: 'A. Bloodline / Vampire Class', def: '第一识别是血脉久到接近博物馆物件的古血女伯爵。造型入口：黑丝绒、家族胸针、极慢手势、低饱和妆面和像肖像画一样停住的正面性。母题：永生把女性权力变成古董制度。张力：她不是青春吸血鬼，而是用衰老缺席、记忆重量和礼仪压迫他人。视觉证据：古董珠宝、暗纹长裙、没有体温的手背、像审阅家谱的目光。边界：避免普通贵妇或恐怖老巫婆。', defEn: 'First read: an old-blood countess whose lineage feels almost museum-like. Styling entry: black velvet, family brooch, extremely slow hands, desaturated makeup, and portrait-like frontality. Motif: immortality turning female power into antique institution. Tension: she is not a youthful vampire, but pressures others through absent aging, memory weight, and etiquette. Visual evidence: antique jewelry, dark patterned gown, cold hand back, and a gaze that reads genealogies. Boundary: avoid a generic noble lady or horror crone.', tags: ['vampire', 'countess', 'old_blood'] },
  { id: 'vampire_hunter_turncoat', name: '叛变吸血鬼猎人', nameEn: 'Vampire-Hunter Turncoat', group: 'A. 血族 / 吸血鬼阶层', groupEn: 'A. Bloodline / Vampire Class', def: '第一识别是猎人装备还在身上、身体却已经倒向血族的叛变者。造型入口：旧猎人外套、银器空袋、脖颈新咬痕、手套下的苍白和不再握稳武器的手。母题：敌人身份被身体背叛。张力：他懂得猎杀血族的每个流程，却被自己的血液状态改写。视觉证据：断裂十字弩带、空银弹盒、遮住伤口的围巾、愧疚和饥饿并存的眼神。边界：避免普通吸血鬼猎人或动作英雄。', defEn: 'First read: a turncoat whose hunter gear remains while the body has already shifted toward the vampires. Styling entry: old hunter coat, empty silver pockets, fresh bite mark, pale skin under gloves, and hands no longer steady on weapons. Motif: enemy identity betrayed by the body. Tension: he knows every vampire-hunting procedure but is rewritten by his own blood state. Visual evidence: broken crossbow strap, empty silver case, scarf hiding the wound, and eyes mixing guilt with hunger. Boundary: avoid a generic vampire hunter or action hero.', tags: ['vampire', 'hunter', 'turncoat'] },
  { id: 'blood_sommelier', name: '血液侍酒师', nameEn: 'Blood Sommelier', group: 'A. 血族 / 吸血鬼阶层', groupEn: 'A. Bloodline / Vampire Class', def: '第一识别是把血液当成品鉴体系的血族侍酒师。造型入口：白衬衫、暗红试管杯、银托盘、嗅闻姿态和过度专业的舌尖克制。母题：欲望被礼仪和分类学高级化。张力：他谈论口感时像谈葡萄酒，画面却始终让人意识到对象是血。视觉证据：标注血型的小瓶、黑围裙、冷静侧脸、拿杯手势。边界：避免血腥餐桌或普通酒保。', defEn: 'First read: a vampire sommelier who treats blood as a tasting system. Styling entry: white shirt, dark-red sample glass, silver tray, smelling posture, and excessively professional restraint at the tongue. Motif: desire elevated by etiquette and taxonomy. Tension: he discusses flavor like wine while the image never forgets the material is blood. Visual evidence: labeled vials, black apron, calm profile, and cup-holding gesture. Boundary: avoid gore dining or generic bartender.', tags: ['vampire', 'sommelier', 'blood'] },
  { id: 'sun_allergy_bride', name: '日光过敏新娘', nameEn: 'Sun-Allergy Bride', group: 'A. 血族 / 吸血鬼阶层', groupEn: 'A. Bloodline / Vampire Class', def: '第一识别是被婚礼白色和日光风险同时包围的血族新娘。造型入口：厚重面纱、遮光手套、白裙下的苍白皮肤、窗边退避姿态和被太阳逼出的恐惧。母题：纯洁仪式与不死身体的物理冲突。张力：她不是害羞，而是必须在祝福光线中躲避灼伤。视觉证据：遮阳伞、微红皮肤边缘、白色蕾丝阴影、抓紧窗帘的手。边界：避免普通病弱新娘或甜美婚纱照。', defEn: 'First read: a vampire bride surrounded by both wedding whiteness and sunlight danger. Styling entry: heavy veil, light-blocking gloves, pallor under the gown, retreating posture near windows, and fear forced out by sun. Motif: purity ritual colliding physically with an undead body. Tension: she is not shy; she must avoid burning inside blessing light. Visual evidence: parasol, reddened skin edge, lace shadow, and hands gripping curtains. Boundary: avoid a generic fragile bride or sweet wedding portrait.', tags: ['vampire', 'bride', 'sunlight'] },
  { id: 'corporate_vampire_ceo', name: '企业血族CEO', nameEn: 'Corporate Vampire CEO', group: 'A. 血族 / 吸血鬼阶层', groupEn: 'A. Bloodline / Vampire Class', def: '第一识别是把吸血阶层更新成资本控制的企业血族CEO。造型入口：极净西装、玻璃会议室、暗红领带、长期不睡的冷脸和像签收血债的钢笔。母题：捕食从身体动作转为合同和绩效制度。张力：他不需要露牙，资产负债表已经替他吸血。视觉证据：股权文件、董事会座位、无影灯般办公室光、干净到无人的手。边界：避免普通霸总或金融精英。', defEn: 'First read: a corporate vampire CEO updating vampiric class into capital control. Styling entry: immaculate suit, glass boardroom, dark-red tie, sleepless cold face, and a pen that seems to sign blood debt. Motif: predation shifting from body action to contract and performance systems. Tension: he need not show fangs; the balance sheet feeds for him. Visual evidence: equity documents, board seat, surgical office light, and hands too clean to feel human. Boundary: avoid generic CEO romance or finance elite.', eras: modernEras, tags: ['vampire', 'ceo', 'corporate'] },

  { id: 'jiangshi_bride', name: '僵尸新娘', nameEn: 'Jiangshi Bride', group: 'B. 僵尸 / 行尸 / 死后身体', groupEn: 'B. Zombie / Walking Dead / Postmortem Body', def: '第一识别是婚礼服制和僵尸身体规则叠在一起的僵尸新娘。造型入口：红盖头、纸符、僵硬手腕、下坠袖口和像被牵线般前移的步态。母题：婚嫁仪式在死后继续执行。张力：她不是浪漫新娘，而是被礼俗、符咒和僵硬关节共同推着走。视觉证据：符纸、绣鞋悬停、苍白脸、红布遮蔽、直立而不自然的姿态。边界：避免普通古装新娘或滑稽僵尸。', defEn: 'First read: a jiangshi bride where wedding dress and undead body rules overlap. Styling entry: red veil, paper talisman, stiff wrists, hanging sleeves, and a puppet-like forward gait. Motif: marriage ritual continuing after death. Tension: she is not romantic; etiquette, talisman, and rigid joints push her forward. Visual evidence: talisman paper, hovering embroidered shoes, pale face, red cloth concealment, and unnaturally upright posture. Boundary: avoid a generic period bride or comic zombie.', tags: ['jiangshi', 'bride', 'talisman'] },
  { id: 'zombie_prom_queen', name: '丧尸舞会皇后', nameEn: 'Zombie Prom Queen', group: 'B. 僵尸 / 行尸 / 死后身体', groupEn: 'B. Zombie / Walking Dead / Postmortem Body', def: '第一识别是舞会胜利形象和尸体状态同时存在的丧尸皇后。造型入口：歪斜王冠、破损亮片裙、毕业舞会缎带、僵硬笑容和拖慢的领奖姿态。母题：青春荣誉在腐败身体上延迟播放。张力：她仍然像在等掌声，但皮肤、步态和空眼神说明派对早已结束。视觉证据：枯萎花束、掉粉妆面、发硬手臂、被泥弄脏的高跟鞋。边界：避免普通舞会女孩或血腥猎奇。', defEn: 'First read: a prom victory image existing simultaneously with corpse state. Styling entry: crooked crown, damaged sequin dress, prom sash, stiff smile, and slowed award posture. Motif: youth honor replaying late on a decaying body. Tension: she still waits for applause while skin, gait, and empty eyes reveal the party is over. Visual evidence: wilted bouquet, crumbling makeup, rigid arms, and mud-stained heels. Boundary: avoid a generic prom girl or gore spectacle.', eras: modernEras, tags: ['zombie', 'prom', 'queen'] },
  { id: 'office_zombie_worker', name: '办公室行尸职员', nameEn: 'Office Zombie Worker', group: 'B. 僵尸 / 行尸 / 死后身体', groupEn: 'B. Zombie / Walking Dead / Postmortem Body', def: '第一识别是被办公室流程榨成行尸的职员。造型入口：皱衬衫、挂歪工牌、灰白脸色、咖啡污渍和继续敲键盘的僵硬手指。母题：劳动节奏比生命本身更晚停止。张力：恐怖感来自日常流程仍在运转，而不是怪物攻击。视觉证据：Excel反光、眼下青黑、拖地领带、失焦眼神、重复打卡姿态。边界：避免普通上班族或末日丧尸群。', defEn: 'First read: an office worker drained into a walking corpse by workflow. Styling entry: wrinkled shirt, crooked badge, gray pallor, coffee stains, and stiff fingers still typing. Motif: labor rhythm stopping later than life itself. Tension: horror comes from daily process still running, not monster attack. Visual evidence: spreadsheet glow, dark under-eyes, dragging tie, unfocused gaze, and repeated clock-in posture. Boundary: avoid a generic office worker or zombie horde.', ontologyLevel: 3, eras: modernEras, tags: ['zombie', 'office', 'worker'] },
  { id: 'revenant_soldier', name: '还魂士兵', nameEn: 'Revenant Soldier', group: 'B. 僵尸 / 行尸 / 死后身体', groupEn: 'B. Zombie / Walking Dead / Postmortem Body', def: '第一识别是被战争命令拉回来的还魂士兵。造型入口：旧军服、泥土、破损肩章、空洞目光和仍保持队列纪律的身体。母题：命令比死亡更顽固。张力：他不是冲锋英雄，而是被未完成任务和战场泥水固定住的残余身体。视觉证据：腐蚀军牌、绷带、弹孔布料、僵硬敬礼、靴底泥。边界：避免普通士兵或动作战斗画面。', defEn: 'First read: a soldier pulled back by orders after death. Styling entry: old uniform, mud, damaged rank marks, hollow gaze, and a body still obeying formation. Motif: command more stubborn than death. Tension: he is not a charging hero but a residual body fixed by unfinished mission and battlefield mud. Visual evidence: corroded dog tag, bandages, bullet-torn cloth, stiff salute, and mud under boots. Boundary: avoid a generic soldier or action battle scene.', tags: ['revenant', 'soldier', 'war'] },
  { id: 'corpse_makeup_artist', name: '尸妆师', nameEn: 'Corpse Makeup Artist', group: 'B. 僵尸 / 行尸 / 死后身体', groupEn: 'B. Zombie / Walking Dead / Postmortem Body', def: '第一识别是用化妆技术把死亡整理成可告别面孔的尸妆师。造型入口：白手套、粉扑、冷色工作服、细小刷具和靠近尸体脸部的稳手。母题：美感服务于丧葬秩序。张力：她不是亡灵本体，而是最懂死亡表面的人。视觉证据：化妆箱、遮瑕色盘、低头专注、冷柜标签、安静职业姿态。边界：避免写成杀手或恐怖巫师。', defEn: 'First read: a mortuary makeup artist using cosmetics to make death a face people can say goodbye to. Styling entry: white gloves, powder puff, cool workwear, small brushes, and steady hands near a corpse face. Motif: beauty serving funeral order. Tension: she is not undead herself, but understands death surface better than anyone. Visual evidence: makeup case, concealer palette, focused lowered head, cold-storage labels, and quiet professional posture. Boundary: avoid making her a killer or horror witch.', ontologyLevel: 1, eras: modernEras, tags: ['mortuary', 'makeup_artist', 'funeral'] },
  { id: 'graveyard_delivery_boy', name: '墓园外卖少年', nameEn: 'Graveyard Delivery Boy', group: 'B. 僵尸 / 行尸 / 死后身体', groupEn: 'B. Zombie / Walking Dead / Postmortem Body', def: '第一识别是把外卖路线送进墓园边界的年轻跑单者。造型入口：保温箱、反光外套、墓碑间穿行的车轮、手机定位和被阴冷环境压低的肩。母题：现代服务劳动进入死亡空间。张力：他不一定是亡灵，但身体被夜班、墓园和订单时间变得像半个死者。视觉证据：雨水、墓园门牌、手机冷光、疲惫眼神、手套握紧车把。边界：避免普通外卖员或鬼故事主角。', defEn: 'First read: a delivery boy whose route enters cemetery borders. Styling entry: insulated box, reflective jacket, wheels between graves, phone GPS, and shoulders lowered by cold air. Motif: modern service labor entering death space. Tension: he may not be undead, but night shift, cemetery, and delivery timer make him half-dead. Visual evidence: rain, cemetery gate sign, phone glow, tired eyes, gloved hands gripping handlebars. Boundary: avoid a generic courier or ghost-story protagonist.', ontologyLevel: 2, eras: modernEras, tags: ['delivery', 'graveyard', 'night_shift'] },
  { id: 'stitched_corpse_girl', name: '缝合尸少女', nameEn: 'Stitched Corpse Girl', group: 'B. 僵尸 / 行尸 / 死后身体', groupEn: 'B. Zombie / Walking Dead / Postmortem Body', def: '第一识别是身体被缝合技术重新拼成可行动状态的少女形尸体。造型入口：不对称皮肤色块、粗细不同的缝线、略错位的关节和像刚学会站稳的姿态。母题：身体不是生长出来，而是被修补出来。张力：可怜感和手工恐怖并存，但必须保持角色可读而非血腥堆叠。视觉证据：补丁衣裙、缝线、不同材质皮肤、僵硬手肘、谨慎眼神。边界：避免纯猎奇尸块或可爱娃娃化。', defEn: 'First read: a girl-corpse reassembled into movement through stitching. Styling entry: asymmetrical skin patches, varied stitches, slightly misaligned joints, and a posture like she just learned to stand. Motif: a body repaired rather than grown. Tension: pity and handmade horror coexist while the character stays readable rather than gore clutter. Visual evidence: patched dress, stitches, mismatched skin materials, stiff elbows, and cautious eyes. Boundary: avoid pure body-horror pieces or cute dollification.', tags: ['stitched', 'corpse', 'patchwork'] },
  { id: 'funeral_home_zombie', name: '殡仪馆丧尸', nameEn: 'Funeral-Home Zombie', group: 'B. 僵尸 / 行尸 / 死后身体', groupEn: 'B. Zombie / Walking Dead / Postmortem Body', def: '第一识别是从殡仪馆流程中滑出的丧尸身体。造型入口：黑西装、遗体编号牌、半整理发型、白花胸针和不该继续站立的脊背。母题：被服务化的死亡突然恢复动作。张力：他仍带着“已被整理好”的体面，却用僵硬眼神破坏告别秩序。视觉证据：灵堂灯、棺木边缘、编号腕带、蜡白妆面、慢半拍步伐。边界：避免普通葬礼宾客或血腥怪物。', defEn: 'First read: a zombie body slipping out of funeral-home procedure. Styling entry: black suit, body ID tag, half-arranged hair, white flower pin, and a spine that should no longer stand. Motif: serviced death suddenly moving again. Tension: he still carries arranged dignity while his stiff gaze breaks farewell order. Visual evidence: funeral-hall light, coffin edge, wrist tag, waxy makeup, and half-beat-late steps. Boundary: avoid a generic funeral guest or gore monster.', eras: modernEras, tags: ['zombie', 'funeral_home', 'corpse'] },
  { id: 'mud_dead_farmer', name: '泥土死者农夫', nameEn: 'Mud-Dead Farmer', group: 'B. 僵尸 / 行尸 / 死后身体', groupEn: 'B. Zombie / Walking Dead / Postmortem Body', def: '第一识别是从土地里被雨水和劳动记忆带回来的死者农夫。造型入口：泥土覆盖的手、旧草帽、湿重衣裤、低垂肩背和像听见季节命令般抬头的动作。母题：土地没有放过劳动者。张力：恐怖感来自农活姿态继续存在，而不是暴力攻击。视觉证据：泥痕、锈农具、裂开的靴、灰白指甲、慢而重的站姿。边界：避免普通乡村老人或稻草人怪物。', defEn: 'First read: a dead farmer brought back from soil by rain and labor memory. Styling entry: mud-covered hands, old straw hat, wet heavy clothing, lowered shoulders, and a head raising as if hearing seasonal command. Motif: the land not releasing the laborer. Tension: horror comes from farm-work posture continuing, not violent attack. Visual evidence: mud marks, rusted tool, cracked boots, gray nails, and slow heavy stance. Boundary: avoid a generic rural elder or scarecrow monster.', tags: ['mud_dead', 'farmer', 'soil'] },
  { id: 'undead_marathon_runner', name: '不死马拉松跑者', nameEn: 'Undead Marathon Runner', group: 'B. 僵尸 / 行尸 / 死后身体', groupEn: 'B. Zombie / Walking Dead / Postmortem Body', def: '第一识别是已经越过生理极限却仍在跑的不死马拉松跑者。造型入口：破损号码布、干裂嘴唇、灰白汗迹、磨烂跑鞋和机械重复的摆臂。母题：竞技意志在死亡后失控延续。张力：他不是健康运动员，而是被终点、计时和身体残余驱动的空壳。视觉证据：旧奖牌、绷带膝盖、塌陷胸腔感、空眼神、跑道边缘。边界：避免普通跑者或丧尸追逐场面。', defEn: 'First read: an undead marathon runner who has crossed biological limits and keeps running. Styling entry: torn bib, cracked lips, gray sweat marks, ruined shoes, and mechanically repeated arm swing. Motif: athletic will continuing out of control after death. Tension: he is not a healthy athlete but a shell driven by finish line, timing, and bodily residue. Visual evidence: old medal, bandaged knees, collapsed chest feeling, empty eyes, and track edge. Boundary: avoid a generic runner or zombie chase scene.', eras: modernEras, tags: ['undead', 'marathon', 'runner'] },

  { id: 'ghost_songstress', name: '幽灵歌姬', nameEn: 'Ghost Songstress', group: 'C. 幽灵 / 怨灵 / 残影', groupEn: 'C. Ghost / Grudge Spirit / Residual Image', def: '第一识别是声音还留在场内、身体却像旧舞台光里的幽灵歌姬。造型入口：复古麦克风、半透明披肩、失焦眼神、过时礼服和像唱到最后一句时停住的手。母题：表演残响比肉身更持久。张力：她不是恐吓观众，而是被掌声和遗憾固定。视觉证据：空剧场、泛白唇妆、微浮裙摆、麦克风线、安静张口。边界：避免普通歌手或尖叫女鬼。', defEn: 'First read: a ghost songstress whose voice remains in the room while the body thins in old stage light. Styling entry: vintage microphone, translucent shawl, unfocused eyes, outdated gown, and a hand stopped at the final lyric. Motif: performance resonance lasting longer than flesh. Tension: she does not scare the audience; applause and regret hold her in place. Visual evidence: empty theater, faded lip color, slightly floating skirt, microphone cable, and quiet open mouth. Boundary: avoid a generic singer or screaming ghost woman.', tags: ['ghost', 'songstress', 'stage'] },
  { id: 'school_ghost_girl', name: '学校幽灵女孩', nameEn: 'School Ghost Girl', group: 'C. 幽灵 / 怨灵 / 残影', groupEn: 'C. Ghost / Grudge Spirit / Residual Image', def: '第一识别是被校服和走廊记忆固定住的学校幽灵女孩。造型入口：旧校服、过白袜子、低垂书包、模糊发梢和站在日光照不到位置的身体。母题：青春没有离开建筑。张力：她的恐怖感来自过度安静和时间错位，不来自怪物器官。视觉证据：空教室门牌、粉笔灰、半透明袖口、迟疑脚尖、看向座位的眼神。边界：避免普通学生或校园恐怖长发模板。', defEn: 'First read: a school ghost girl fixed by uniform and corridor memory. Styling entry: old uniform, too-white socks, lowered satchel, blurred hair ends, and a body standing outside sunlight. Motif: youth unable to leave the building. Tension: fear comes from excessive quiet and temporal mismatch, not monster organs. Visual evidence: empty classroom sign, chalk dust, translucent sleeve edge, hesitant toes, and gaze toward a desk. Boundary: avoid a generic student or long-haired school-horror template.', eras: modernEras, tags: ['ghost', 'school', 'girl'] },
  { id: 'elevator_death_spirit', name: '电梯死灵', nameEn: 'Elevator Death Spirit', group: 'C. 幽灵 / 怨灵 / 残影', groupEn: 'C. Ghost / Grudge Spirit / Residual Image', def: '第一识别是被电梯间狭窄空间和楼层数字困住的死灵。造型入口：金属门反光、楼层灯、压迫性垂直站姿、被门缝切开的脸和像等待开门却永远不开的手。母题：现代建筑里的重复死亡。张力：她不需要大场景，幽灵感来自封闭、反射和楼层错位。视觉证据：电梯按钮光、金属镜面、半透明肩线、卡住的门缝姿态。边界：避免普通通勤者或血腥事故画面。', defEn: 'First read: a death spirit trapped by elevator narrowness and floor numbers. Styling entry: metal-door reflection, floor light, pressured vertical posture, face sliced by the door gap, and a hand waiting for doors that never open. Motif: repeated death inside modern architecture. Tension: no large scene is needed; ghostliness comes from enclosure, reflection, and floor mismatch. Visual evidence: button glow, metal mirror, translucent shoulder line, and stuck-door posture. Boundary: avoid a generic commuter or gore accident scene.', eras: modernEras, tags: ['ghost', 'elevator', 'modern'] },
  { id: 'wedding_photo_ghost', name: '婚纱照幽灵', nameEn: 'Wedding-Photo Ghost', group: 'C. 幽灵 / 怨灵 / 残影', groupEn: 'C. Ghost / Grudge Spirit / Residual Image', def: '第一识别是从过曝婚纱照里残留下来的幽灵新娘影像。造型入口：白婚纱、相册边框、过亮面部、失真微笑和像被定格在快门里的手。母题：幸福图像变成未完成的死亡证明。张力：她不是现实婚礼人物，而是照片本身留下的残影。视觉证据：相纸颗粒、白纱溶边、旧影楼姿态、空白新郎位置、褪色花束。边界：避免普通婚纱照或恐怖新娘突袭。', defEn: 'First read: a ghost bride residue left inside an overexposed wedding photo. Styling entry: white dress, album border, too-bright face, distorted smile, and a hand frozen in shutter time. Motif: happiness image becoming unfinished death proof. Tension: she is not a real wedding figure but the photograph residue. Visual evidence: photo grain, dissolving veil edge, old studio pose, empty groom position, and faded bouquet. Boundary: avoid a normal bridal portrait or attacking horror bride.', eras: modernEras, tags: ['ghost', 'wedding_photo', 'bride'] },
  { id: 'theater_balcony_specter', name: '剧院包厢幽灵', nameEn: 'Theater-Balcony Specter', group: 'C. 幽灵 / 怨灵 / 残影', groupEn: 'C. Ghost / Grudge Spirit / Residual Image', def: '第一识别是旧剧院包厢里永远看着舞台的幽灵观众。造型入口：歌剧镜、暗红包厢、旧礼服、半遮面孔和不鼓掌的手。母题：观看行为本身变成亡灵身份。张力：他不是演员，而是被某场演出永远扣在观众席。视觉证据：磨损扶手、灰尘、冷白脸、凝固坐姿、望远镜反光。边界：避免普通贵族观众或舞台鬼怪。', defEn: 'First read: a ghost spectator in an old theater balcony, forever watching the stage. Styling entry: opera glasses, dark-red box, old formalwear, half-hidden face, and hands that never applaud. Motif: the act of watching becoming undead identity. Tension: he is not the performer, but trapped in the audience by one performance. Visual evidence: worn rail, dust, cold pale face, frozen seated posture, and binocular glint. Boundary: avoid a generic noble spectator or stage monster.', tags: ['specter', 'theater', 'balcony'] },
  { id: 'train_station_ghost_boy', name: '车站幽灵少年', nameEn: 'Train-Station Ghost Boy', group: 'C. 幽灵 / 怨灵 / 残影', groupEn: 'C. Ghost / Grudge Spirit / Residual Image', def: '第一识别是一直停在站台边缘等待一班不存在列车的幽灵少年。造型入口：旧书包、站台灯、薄外套、半透明鞋尖和看向轨道尽头的脸。母题：离别动作被时间卡住。张力：他不是迷路孩子，而是整个身体都被等待姿态定义。视觉证据：车票、站牌、雾气、低头手指、无法被人群碰到的距离。边界：避免普通旅客或煽情儿童故事。', defEn: 'First read: a ghost boy waiting at a platform edge for a train that no longer exists. Styling entry: old schoolbag, platform light, thin coat, translucent shoe tips, and a face turned down the track. Motif: farewell action stuck in time. Tension: he is not a lost child; the whole body is defined by waiting. Visual evidence: ticket, station sign, mist, lowered fingers, and distance no crowd can touch. Boundary: avoid a generic traveler or sentimental child story.', eras: modernEras, tags: ['ghost', 'train_station', 'boy'] },
  { id: 'radio_static_spirit', name: '电台杂音亡灵', nameEn: 'Radio-Static Spirit', group: 'C. 幽灵 / 怨灵 / 残影', groupEn: 'C. Ghost / Grudge Spirit / Residual Image', def: '第一识别是通过电台杂音显影的亡灵。造型入口：旧耳机、收音机旋钮、灰白噪点般的边缘、断续口型和像信号不稳一样错位的肩线。母题：声音媒介把死亡重新拼成脸。张力：她不应变成数字故障人，而是旧广播时代的幽灵残响。视觉证据：天线、频率刻度、静电发丝、半透明喉部、听不清的表情。边界：避免现代赛博屏幕故障或普通播音员。', defEn: 'First read: a spirit made visible through radio static. Styling entry: old headphones, radio dial, gray-white noisy edges, broken mouth shape, and shoulders offset like unstable signal. Motif: sound medium reassembling death into a face. Tension: she should not become a digital glitch person, but a ghost residue from radio age. Visual evidence: antenna, frequency marks, static hair, translucent throat, and an expression that cannot be heard clearly. Boundary: avoid modern cyber-screen glitch or generic announcer.', eras: modernEras, tags: ['ghost', 'radio', 'static'] },
  { id: 'haunted_housemaid', name: '鬼宅女仆', nameEn: 'Haunted Housemaid', group: 'C. 幽灵 / 怨灵 / 残影', groupEn: 'C. Ghost / Grudge Spirit / Residual Image', def: '第一识别是仍按旧宅规矩整理空间的鬼宅女仆。造型入口：黑白女仆服、冷掉的抹布、楼梯阴影、半垂眼和像刚听见主人铃声的停顿。母题：服务关系在死亡后继续运转。张力：她不是可爱女仆，而是被宅邸和阶级纪律困住的残影。视觉证据：钥匙串、灰尘、围裙褶皱、轻微透明手腕、低头侧身。边界：避免萌系女仆或随机鬼怪。', defEn: 'First read: a haunted housemaid still arranging space by old household rules. Styling entry: black-white maid dress, cold rag, stair shadow, lowered eyes, and a pause as if hearing the household bell. Motif: service relation continuing after death. Tension: she is not a cute maid but a residue trapped by house and class discipline. Visual evidence: keys, dust, apron folds, slightly transparent wrist, and lowered side posture. Boundary: avoid moe maid or random ghost monster.', tags: ['ghost', 'housemaid', 'estate'] },
  { id: 'mirror_ghost_twin', name: '镜中幽灵双胞胎', nameEn: 'Mirror-Ghost Twin', group: 'C. 幽灵 / 怨灵 / 残影', groupEn: 'C. Ghost / Grudge Spirit / Residual Image', def: '第一识别是镜面里多出来的幽灵双胞胎，而不是两个普通人物。造型入口：相同发型、错位眼神、镜面边框、一个身体略微透明和不一致的手势。母题：身份被反射复制后留下死亡差异。张力：相似性必须让人不安，差异来自透明度、方向和延迟动作。视觉证据：旧镜框、雾面玻璃、反向衣扣、一个人看镜头另一个看别处。边界：避免普通双胞胎写真。', defEn: 'First read: an extra ghost twin inside the mirror, not two normal people. Styling entry: matching hair, offset gaze, mirror frame, one slightly transparent body, and mismatched gestures. Motif: identity copied by reflection and marked by death difference. Tension: similarity must unsettle; difference comes from transparency, direction, and delayed motion. Visual evidence: old frame, fogged glass, reversed buttons, one looking at camera while the other looks elsewhere. Boundary: avoid a normal twin portrait.', tags: ['ghost', 'mirror', 'twin'] },
  { id: 'battlefield_specter_nurse', name: '战场幽灵护士', nameEn: 'Battlefield Specter Nurse', group: 'C. 幽灵 / 怨灵 / 残影', groupEn: 'C. Ghost / Grudge Spirit / Residual Image', def: '第一识别是战争结束后仍在寻找伤员的幽灵护士。造型入口：旧护士帽、染灰围裙、绷带箱、泥点、半透明袖口和随时要蹲下包扎的身体。母题：照护职责无法随死亡结束。张力：她不恐吓人，而是被救援动作困住。视觉证据：医疗包、旧红十字标记、疲惫脸、空手托住不存在伤口的姿态。边界：避免普通护士或战场动作角色。', defEn: 'First read: a ghost nurse still searching for wounded after war has ended. Styling entry: old nurse cap, gray-stained apron, bandage case, mud marks, translucent cuffs, and a body ready to kneel and dress wounds. Motif: care duty unable to end with death. Tension: she does not frighten people; rescue motion traps her. Visual evidence: medical kit, old red-cross mark, tired face, and hands supporting an absent wound. Boundary: avoid a generic nurse or battlefield action character.', tags: ['ghost', 'nurse', 'battlefield'] },

  { id: 'skeleton_knight', name: '骷髅骑士', nameEn: 'Skeleton Knight', group: 'D. 骷髅 / 骨骸 / 死亡骑士', groupEn: 'D. Skeleton / Bone Body / Death Knight', def: '第一识别是骑士身份仍挂在骨骼上的骷髅骑士。造型入口：空眼窝、残破披风、锈甲、骨手握剑和像仍遵守誓言的站姿。母题：荣誉制度比肉身更晚腐烂。张力：他不是普通骷髅怪，而是被盔甲、徽记和礼节维持身份。视觉证据：断裂纹章、骨节、磨损剑鞘、无肉但端正的肩线。边界：避免游戏怪物小兵或全套亮新盔甲。', defEn: 'First read: a skeleton knight whose knightly identity still hangs on bone. Styling entry: empty sockets, torn cloak, rusted armor, bone hand on sword, and a stance still obeying oath. Motif: honor system rotting later than flesh. Tension: he is not a generic skeleton monster, but maintained by armor, heraldry, and etiquette. Visual evidence: broken crest, bone joints, worn scabbard, and fleshless yet upright shoulders. Boundary: avoid game mob skeleton or shiny full armor.', tags: ['skeleton', 'knight', 'armor'] },
  { id: 'bone_crown_king', name: '骨冠国王', nameEn: 'Bone-Crown King', group: 'D. 骷髅 / 骨骸 / 死亡骑士', groupEn: 'D. Skeleton / Bone Body / Death Knight', def: '第一识别是王权已经与骨骼长在一起的骨冠国王。造型入口：由肋骨或指骨组成的王冠、空洞脸、残破王袍和不需要臣民也能维持命令的坐姿。母题：统治权在死亡后变成结构。张力：他不应像恐怖骷髅，而要像制度化尸骨。视觉证据：骨冠、权杖、王座灰尘、裂开的下颌、仍压迫空间的正面性。边界：避免普通骷髅王怪物。', defEn: 'First read: a king whose crown and bones have become one structure. Styling entry: crown made of ribs or finger bones, hollow face, ruined robe, and a seated posture that commands without subjects. Motif: sovereignty becoming structure after death. Tension: he should not read as a horror skeleton but as institutionalized remains. Visual evidence: bone crown, scepter, throne dust, cracked jaw, and frontal pressure still occupying space. Boundary: avoid a generic skeleton king monster.', ontologyLevel: 5, tags: ['skeleton', 'king', 'bone_crown'] },
  { id: 'skull_mask_dancer', name: '骷髅面具舞者', nameEn: 'Skull-Mask Dancer', group: 'D. 骷髅 / 骨骸 / 死亡骑士', groupEn: 'D. Skeleton / Bone Body / Death Knight', def: '第一识别是用骷髅面具把舞蹈变成死亡礼仪的舞者。造型入口：白骨面具、露出的下颌线、黑色舞衣、脚踝铃和像绕着祭台转身的身体。母题：死亡被表演化。张力：骷髅可以是面具或本体证据，但动作必须优雅、节制、有仪式节拍。视觉证据：骨纹面具、长袖、旋转手腕、铃声道具、遮住真实表情的脸。边界：避免普通万圣节装扮或狂欢骷髅。', defEn: 'First read: a dancer turning movement into death ritual through a skull mask. Styling entry: bone-white mask, visible jaw line, black dancewear, ankle bells, and a body circling as if around an altar. Motif: death becoming performance. Tension: the skull may be mask or body evidence, but movement must stay elegant, restrained, and ritual-beat driven. Visual evidence: bone-pattern mask, long sleeves, rotating wrists, bell props, and a face hiding true expression. Boundary: avoid Halloween costume or carnival skeleton.', tags: ['skull_mask', 'dancer', 'ritual'] },
  { id: 'ossuary_monk', name: '藏骨堂僧侣', nameEn: 'Ossuary Monk', group: 'D. 骷髅 / 骨骸 / 死亡骑士', groupEn: 'D. Skeleton / Bone Body / Death Knight', def: '第一识别是在骨墙之间修行的藏骨堂僧侣。造型入口：粗布僧袍、骨珠、低头合掌、干燥皮肤或骨质边缘和像听见骨头回声的安静。母题：死亡成为日常纪律。张力：他不是恐怖祭司，而是把尸骨秩序当作沉默修行。视觉证据：骨珠念串、蜡烛、石壁、手指贴骨、无表情的虔敬。边界：避免真实宗教冒犯或恶魔化僧侣。', defEn: 'First read: a monk practicing among ossuary walls. Styling entry: coarse robe, bone beads, bowed prayer hands, dry skin or bony edges, and quiet as if hearing bone echoes. Motif: death as daily discipline. Tension: he is not a horror priest but treats skeletal order as silent practice. Visual evidence: bone rosary, candles, stone wall, fingers touching bone, and expressionless devotion. Boundary: avoid real religious offense or demonizing monkhood.', tags: ['ossuary', 'monk', 'bones'] },
  { id: 'bone_violinist', name: '骨琴师', nameEn: 'Bone Violinist', group: 'D. 骷髅 / 骨骸 / 死亡骑士', groupEn: 'D. Skeleton / Bone Body / Death Knight', def: '第一识别是用骨质乐器或骨手演奏的死亡琴师。造型入口：骨白小提琴、细长手指、黑色演出服、空洞或极瘦脸部和拉弓时像在切割空气的姿态。母题：音乐从遗骸里发声。张力：优雅必须压住恐怖，让骨质成为声音和身份证据。视觉证据：骨弓、旧乐谱、露骨手腕、阴影舞台、专注侧脸。边界：避免普通乐手或滑稽骷髅乐队。', defEn: 'First read: a death violinist playing through bone instrument or bone hands. Styling entry: bone-white violin, long fingers, black concert clothes, hollow or extremely thin face, and a bowing posture like slicing air. Motif: music sounding from remains. Tension: elegance must restrain horror, making bone material evidence for sound and identity. Visual evidence: bone bow, old score, exposed wrist bones, shadowed stage, and focused profile. Boundary: avoid a generic musician or comic skeleton band.', tags: ['bone', 'violinist', 'music'] },
  { id: 'death_horseman_cadet', name: '死亡骑士学徒', nameEn: 'Death-Knight Cadet', group: 'D. 骷髅 / 骨骸 / 死亡骑士', groupEn: 'D. Skeleton / Bone Body / Death Knight', def: '第一识别是还没完全长成死亡骑士的学徒。造型入口：过大的黑甲、骨质护符、训练木剑、青白脸和努力保持威严却露出紧张的站姿。母题：死亡制度里的新人。张力：他带有死亡阵营符号，但还不够沉稳，身体里有笨拙和未完成感。视觉证据：松动甲带、磨旧护膝、导师留下的骨徽、握剑过紧的手。边界：避免成熟死亡骑士或普通少年骑士。', defEn: 'First read: a cadet not yet fully grown into a death knight. Styling entry: oversized black armor, bone amulet, training sword, bluish pale face, and a stance trying to be solemn while showing nerves. Motif: a newcomer inside death institution. Tension: he carries death-faction signs but not full authority; the body feels awkward and unfinished. Visual evidence: loose armor straps, worn kneepads, mentor bone badge, and hands gripping the sword too tightly. Boundary: avoid a mature death knight or generic young knight.', tags: ['death_knight', 'cadet', 'training'] },
  { id: 'bone_armor_princess', name: '骨甲公主', nameEn: 'Bone-Armor Princess', group: 'D. 骷髅 / 骨骸 / 死亡骑士', groupEn: 'D. Skeleton / Bone Body / Death Knight', def: '第一识别是礼服和骨甲合成一体的死亡公主。造型入口：骨片胸衣、象牙色裙摆、王室发饰、僵白手臂和像被保护也被囚禁的站姿。母题：脆弱贵族身体被死亡材料武装。张力：骨甲不能变成普通战甲，必须像宫廷服制的一部分压住她。视觉证据：肋骨形胸衣、骨珠、苍白妆、拖尾、手臂被限制的姿态。边界：避免普通公主或女战士。', defEn: 'First read: a death princess whose gown and bone armor are fused. Styling entry: bone-plate bodice, ivory skirt, royal hairpiece, white arms, and a stance both protected and imprisoned. Motif: fragile noble body armed by death material. Tension: bone armor must not become generic battle armor; it should press her as part of court dress. Visual evidence: rib-shaped corset, bone beads, pale makeup, train, and arms constrained by structure. Boundary: avoid generic princess or warrior woman.', tags: ['bone_armor', 'princess', 'court'] },
  { id: 'grave_bone_collector', name: '墓地拾骨人', nameEn: 'Grave Bone Collector', group: 'D. 骷髅 / 骨骸 / 死亡骑士', groupEn: 'D. Skeleton / Bone Body / Death Knight', def: '第一识别是在墓地边缘按重量、形状和名字整理骨头的人。造型入口：布袋、手套、骨刷、低头搜索姿态和不把骨头当恐怖物的平静。母题：死亡材料的劳动者。张力：他不是盗墓贼，而是用职业动作把遗骨重新纳入秩序。视觉证据：标签绳、小铲、分类盒、泥点、蹲姿、看骨节的专注眼神。边界：避免普通拾荒者或邪恶盗墓人。', defEn: 'First read: a person at the cemetery edge sorting bones by weight, shape, and names. Styling entry: cloth bag, gloves, bone brush, lowered searching posture, and calmness that does not treat bones as horror. Motif: laborer of death material. Tension: he is not a grave robber but uses professional motion to return remains to order. Visual evidence: label strings, small shovel, sorting box, mud spots, crouch, and focused gaze at joints. Boundary: avoid generic scavenger or evil tomb robber.', ontologyLevel: 2, tags: ['grave', 'bone_collector', 'labor'] },
  { id: 'skeleton_court_jester', name: '骷髅宫廷小丑', nameEn: 'Skeleton Court Jester', group: 'D. 骷髅 / 骨骸 / 死亡骑士', groupEn: 'D. Skeleton / Bone Body / Death Knight', def: '第一识别是笑话已经腐烂、职责还在继续的骷髅宫廷小丑。造型入口：破铃铛帽、骨手、褪色彩衣、空洞笑口和向王座鞠躬的夸张姿态。母题：娱乐权力直到死后仍要表演。张力：滑稽外壳必须带有疲惫和压迫，不是快乐骷髅。视觉证据：裂铃、骨节、补丁衣、夸张但僵硬的弯腰、看不见眼神的笑。边界：避免卡通小丑。', defEn: 'First read: a skeleton court jester whose jokes have rotted while the duty continues. Styling entry: broken bell cap, bone hands, faded motley, hollow grin, and exaggerated bow toward the throne. Motif: entertaining power even after death. Tension: comic shell must carry fatigue and pressure, not joyful skeleton energy. Visual evidence: cracked bells, bone joints, patched costume, exaggerated stiff bow, and smile without eyes. Boundary: avoid cartoon clown.', tags: ['skeleton', 'jester', 'court'] },
  { id: 'ivory_bone_survivor', name: '象牙骨幸存者', nameEn: 'Ivory-Bone Survivor', group: 'D. 骷髅 / 骨骸 / 死亡骑士', groupEn: 'D. Skeleton / Bone Body / Death Knight', def: '第一识别是身体局部已经骨质化、却仍保持生者身份的幸存者。造型入口：象牙色骨片从皮肤边缘露出、简单衣物、护住骨化部位的手和不愿被当成怪物的脸。母题：活人与遗骨之间的迟缓转换。张力：骨质美感要克制，不能变成华丽怪物装饰。视觉证据：骨化手臂、干净绷带、低饱和皮肤、保护性姿态、被触碰前缩回的动作。边界：避免全身骷髅或普通病弱角色。', defEn: 'First read: a survivor whose body has partly ossified while still keeping living identity. Styling entry: ivory bone plates emerging at skin edges, simple clothing, hands protecting ossified parts, and a face refusing to be treated as monster. Motif: slow conversion between living person and remains. Tension: bone beauty should be restrained, not ornate monster decoration. Visual evidence: ossified arm, clean bandage, desaturated skin, protective posture, and a movement pulling back before touch. Boundary: avoid full skeleton or generic sickly character.', ontologyLevel: 3, tags: ['ossified', 'survivor', 'bone'] },

  { id: 'cursed_prince', name: '诅咒王子', nameEn: 'Cursed Prince', group: 'E. 诅咒贵族 / 衰败家族', groupEn: 'E. Cursed Nobility / Decayed Family', def: '第一识别是王室礼仪还在、身体或命运已经被诅咒侵蚀的王子。造型入口：旧王冠、苍白手套、锁骨处封印纹、没有睡眠的眼神和把痛苦压成礼貌的站姿。母题：继承权变成身体惩罚。张力：他不是悲情帅哥，而是每个贵族符号都带着代价。视觉证据：破损绶带、封印戒指、冷汗、略僵硬的微笑、被衣领遮住的咒痕。边界：避免普通童话王子。', defEn: 'First read: a prince whose royal etiquette remains while body or fate is eroded by curse. Styling entry: old crown, pale gloves, seal mark near collarbone, sleepless eyes, and a stance compressing pain into courtesy. Motif: inheritance turning into bodily punishment. Tension: he is not merely a tragic handsome prince; every noble sign carries cost. Visual evidence: damaged sash, seal ring, cold sweat, stiff smile, and curse marks hidden by collar. Boundary: avoid generic fairy-tale prince.', tags: ['curse', 'prince', 'nobility'] },
  { id: 'decayed_duchess', name: '衰败女公爵', nameEn: 'Decayed Duchess', group: 'E. 诅咒贵族 / 衰败家族', groupEn: 'E. Cursed Nobility / Decayed Family', def: '第一识别是把家族衰败穿成日常威严的女公爵。造型入口：旧蕾丝、暗色珠宝、干枯手部、修补礼服和不承认破产的挺直背。母题：阶层死亡比身体死亡更慢。张力：她不应像恐怖鬼魂，而是像仍维持账面体面的腐朽权力。视觉证据：裂纹珍珠、褪色肖像、黑手套、严厉下巴、空宅背景。边界：避免普通贵妇或女巫。', defEn: 'First read: a duchess wearing family decay as daily authority. Styling entry: old lace, dark jewelry, dried hands, repaired gown, and a straight back refusing bankruptcy. Motif: class dying slower than the body. Tension: she should not read as a horror ghost but as rotting power still maintaining formal accounts. Visual evidence: cracked pearls, faded portraits, black gloves, stern chin, and empty manor context. Boundary: avoid generic noblewoman or witch.', tags: ['decay', 'duchess', 'nobility'] },
  { id: 'haunted_manor_heir', name: '鬼宅继承人', nameEn: 'Haunted-Manor Heir', group: 'E. 诅咒贵族 / 衰败家族', groupEn: 'E. Cursed Nobility / Decayed Family', def: '第一识别是继承了一栋宅邸也继承了宅邸阴影的人。造型入口：钥匙串、旧西装或黑裙、墙纸霉斑、被走廊拉长的身影和对每个房间都过度熟悉的眼神。母题：空间作为遗产吞噬主体。张力：他不是鬼屋访客，而是被房子承认为所有物。视觉证据：房契、旧钥匙、潮湿袖口、家族画像、站在门槛上的身体。边界：避免普通富家继承人。', defEn: 'First read: an heir who inherits both manor and manor shadow. Styling entry: keyring, old suit or black dress, mildewed wallpaper, corridor-stretched silhouette, and eyes too familiar with every room. Motif: space as inheritance consuming the subject. Tension: they are not a haunted-house visitor but something the house recognizes as property. Visual evidence: deed, old keys, damp cuffs, family portraits, and body on thresholds. Boundary: avoid generic wealthy heir.', tags: ['haunted_manor', 'heir', 'estate'] },
  { id: 'mirror_curse_count', name: '镜咒伯爵', nameEn: 'Mirror-Curse Count', group: 'E. 诅咒贵族 / 衰败家族', groupEn: 'E. Cursed Nobility / Decayed Family', def: '第一识别是被镜子诅咒分裂出形象和身体的伯爵。造型入口：银镜、裂纹反射、精致礼服、真实脸与镜中脸不一致的视线。母题：贵族自我被反射审判。张力：异常必须落在反射、姿态和面部错位上，不要变成普通变脸怪物。视觉证据：手杖、镜框、反向扣子、镜中年轻或腐烂的另一张脸。边界：避免纯魔法镜剧情。', defEn: 'First read: a count split by mirror curse between image and body. Styling entry: silver mirror, cracked reflection, refined formalwear, and mismatched gaze between real face and reflected face. Motif: aristocratic self judged by reflection. Tension: anomaly must land in reflection, posture, and facial mismatch, not generic shapeshifting monster. Visual evidence: cane, mirror frame, reversed buttons, and a younger or decayed other face in glass. Boundary: avoid pure magic-mirror plot.', tags: ['mirror_curse', 'count', 'reflection'] },
  { id: 'rose_thorn_widow', name: '玫瑰荆棘寡妇', nameEn: 'Rose-Thorn Widow', group: 'E. 诅咒贵族 / 衰败家族', groupEn: 'E. Cursed Nobility / Decayed Family', def: '第一识别是哀悼服和荆棘生长纠缠的诅咒寡妇。造型入口：黑色面纱、干玫瑰、细荆棘沿手套或领口蔓延、压住悲伤的下巴。母题：婚姻、丧偶和身体惩罚长成同一种装饰。张力：玫瑰不能只是浪漫花，要像礼仪无法拔掉的刺。视觉证据：刺破蕾丝、暗红干花、黑裙、手背血点、冷静正面姿态。边界：避免普通哥特玫瑰美人。', defEn: 'First read: a cursed widow whose mourning dress and thorn growth intertwine. Styling entry: black veil, dried roses, fine thorns spreading along gloves or collar, and a chin holding grief down. Motif: marriage, widowhood, and bodily punishment growing into one ornament. Tension: roses must not be just romantic flowers; they are thorns that etiquette cannot remove. Visual evidence: thorns piercing lace, dark-red dried flowers, black dress, blood points on hand, and calm frontality. Boundary: avoid generic goth rose beauty.', tags: ['widow', 'rose', 'thorn'] },
  { id: 'family_curse_lawyer', name: '家族诅咒律师', nameEn: 'Family-Curse Lawyer', group: 'E. 诅咒贵族 / 衰败家族', groupEn: 'E. Cursed Nobility / Decayed Family', def: '第一识别是用法律文件管理超自然家族债务的律师。造型入口：深色西装、旧契约、红蜡封、疲惫眼镜和像宣读遗嘱一样宣读诅咒条款的手势。母题：诅咒被现代制度文书化。张力：他不需要会魔法，危险来自他知道每个名字和继承顺位。视觉证据：档案夹、家谱、印章、钢笔、冷静但不洁净的办公桌。边界：避免普通律师或法师。', defEn: 'First read: a lawyer managing supernatural family debt through legal documents. Styling entry: dark suit, old contract, red wax seal, tired glasses, and a gesture reading curse clauses like a will. Motif: curse turned into modern paperwork. Tension: he need not cast spells; danger comes from knowing every name and inheritance order. Visual evidence: files, family tree, seal, fountain pen, and a calm but unclean desk. Boundary: avoid generic lawyer or wizard.', ontologyLevel: 3, eras: modernEras, tags: ['curse', 'lawyer', 'family'] },
  { id: 'porcelain_mask_heir', name: '瓷面具继承人', nameEn: 'Porcelain-Mask Heir', group: 'E. 诅咒贵族 / 衰败家族', groupEn: 'E. Cursed Nobility / Decayed Family', def: '第一识别是用瓷面具遮住家族诅咒脸部后果的继承人。造型入口：白瓷面具、细裂纹、礼服领口、安静手套和不让人看见真脸的转头。母题：体面依靠遮蔽维持。张力：面具不是装饰，而是社交资格本身。视觉证据：绑带、瓷裂、眼孔阴影、家徽扣、拒绝摘下面具的手。边界：避免普通假面舞会角色。', defEn: 'First read: an heir using a porcelain mask to hide facial consequences of family curse. Styling entry: white porcelain mask, hairline cracks, formal collar, quiet gloves, and head turn refusing the true face. Motif: dignity maintained by concealment. Tension: the mask is not decoration but social qualification itself. Visual evidence: straps, porcelain cracks, eye-hole shadow, house clasp, and a hand refusing removal. Boundary: avoid generic masquerade character.', tags: ['porcelain_mask', 'heir', 'curse'] },
  { id: 'black_ballroom_bride', name: '黑舞会新娘', nameEn: 'Black-Ballroom Bride', group: 'E. 诅咒贵族 / 衰败家族', groupEn: 'E. Cursed Nobility / Decayed Family', def: '第一识别是婚礼被诅咒改写成黑色舞会的新娘。造型入口：黑色婚纱、空舞伴位置、蜡烛、拖尾和像等一支不会开始的舞的姿态。母题：婚礼仪式被死亡社交吞没。张力：她不是普通黑裙美人，而是被舞会规训困在未完成婚约里。视觉证据：黑纱、白花变暗、舞会手套、僵硬脚尖、空中递出的手。边界：避免甜酷婚纱或吸血鬼新娘模板。', defEn: 'First read: a bride whose wedding has been rewritten into a black ballroom by curse. Styling entry: black bridal gown, empty partner position, candles, train, and a posture waiting for a dance that will not begin. Motif: wedding ritual swallowed by death sociality. Tension: she is not a generic black-dress beauty but trapped in unfinished marriage by ballroom discipline. Visual evidence: black veil, darkened white flowers, ballroom gloves, stiff toes, and a hand offered into air. Boundary: avoid sweet edgy bridal fashion or vampire bride template.', tags: ['black_bride', 'ballroom', 'curse'] },
  { id: 'ancestral_portrait_girl', name: '祖先画像女孩', nameEn: 'Ancestral-Portrait Girl', group: 'E. 诅咒贵族 / 衰败家族', groupEn: 'E. Cursed Nobility / Decayed Family', def: '第一识别是像从祖先画像中被家族召回的女孩。造型入口：旧式裙装、画框式正面姿态、褪色皮肤、与画像同款发饰和不属于当前时代的安静。母题：家族记忆把年轻身体变成肖像。张力：她不是复古少女，而是被继承逻辑固定成可替换祖先。视觉证据：油画色调、家徽、过时袖型、正面凝视、像刚离开画布的边缘。边界：避免普通古典女孩。', defEn: 'First read: a girl summoned back from an ancestral portrait. Styling entry: old dress, frame-like frontality, faded skin, matching portrait hairpiece, and quietness from another era. Motif: family memory turning a young body into a portrait. Tension: she is not a vintage girl but a replaceable ancestor fixed by inheritance logic. Visual evidence: oil-painting tone, house crest, outdated sleeves, frontal stare, and edges as if just leaving canvas. Boundary: avoid generic classical girl.', tags: ['ancestral_portrait', 'girl', 'family'] },
  { id: 'ruined_chateau_boy', name: '废堡少年', nameEn: 'Ruined-Chateau Boy', group: 'E. 诅咒贵族 / 衰败家族', groupEn: 'E. Cursed Nobility / Decayed Family', def: '第一识别是在废弃城堡里长大、把破败当作家族体面的少年。造型入口：不合身礼服外套、石灰灰尘、破窗光、细瘦身体和仍试图像贵族一样站直的姿态。母题：贵族教育在废墟中继续。张力：他不是流浪儿，衣服和姿态仍显示被旧秩序训练过。视觉证据：裂墙、旧书、家徽残片、灰白袖口、警惕又骄傲的眼神。边界：避免普通城堡孤儿。', defEn: 'First read: a boy raised in a ruined chateau, treating decay as family dignity. Styling entry: ill-fitting formal jacket, lime dust, broken-window light, thin body, and a posture still trying to stand like nobility. Motif: aristocratic education continuing inside ruins. Tension: he is not a stray child; clothing and posture still show old-order training. Visual evidence: cracked walls, old books, crest fragments, gray cuffs, and wary proud eyes. Boundary: avoid generic castle orphan.', tags: ['ruined_chateau', 'boy', 'nobility'] },

  { id: 'mummy_princess', name: '木乃伊公主', nameEn: 'Mummy Princess', group: 'F. 木乃伊 / 古墓 / 封印者', groupEn: 'F. Mummy / Tomb / Sealed One', def: '第一识别是王室身份和防腐封存同时可读的木乃伊公主。造型入口：亚麻绷带、金饰、干燥皮肤、半遮眼妆和像被从石棺中扶起的姿态。母题：王权被保存技术延迟成不死身体。张力：她不能只是异域公主，身体必须有封存、脱水和墓室材料证据。视觉证据：金项圈、护符、绷带层、沙尘、僵硬手腕。边界：避免普通埃及风美人。', defEn: 'First read: a mummy princess whose royal status and preservation are both readable. Styling entry: linen wraps, gold ornaments, dried skin, half-covered eye makeup, and a posture as if lifted from a sarcophagus. Motif: royalty delayed into undead body by preservation craft. Tension: she cannot be merely exotic princess; the body needs sealing, dehydration, and tomb-material evidence. Visual evidence: gold collar, amulets, bandage layers, dust, and stiff wrists. Boundary: avoid generic Egyptian-style beauty.', eras: ancientEras, tags: ['mummy', 'princess', 'tomb'] },
  { id: 'tomb_guardian_scribe', name: '古墓守书记官', nameEn: 'Tomb-Guardian Scribe', group: 'F. 木乃伊 / 古墓 / 封印者', groupEn: 'F. Mummy / Tomb / Sealed One', def: '第一识别是死后仍守着墓室文字的书记官。造型入口：芦苇笔、石板、干燥手指、封尘衣褶和像正在核对禁忌名单的低头姿态。母题：文字把死者职责固定。张力：他不是战斗守卫，而是用记录、诅咒和封印秩序守墓。视觉证据：石刻符号、墨迹、卷轴、护符、眼窝阴影。边界：避免普通古代文官或怪物法师。', defEn: 'First read: a scribe still guarding tomb writing after death. Styling entry: reed pen, stone tablet, dried fingers, dust-sealed folds, and lowered posture checking forbidden names. Motif: writing fixing duty after death. Tension: he is not a battle guard but protects the tomb through record, curse, and seal order. Visual evidence: carved signs, ink marks, scrolls, amulets, and eye-socket shadow. Boundary: avoid generic ancient official or monster mage.', eras: ancientEras, tags: ['mummy', 'scribe', 'guardian'] },
  { id: 'wrapped_pharaoh_child', name: '绷带法老童', nameEn: 'Wrapped Pharaoh Child', group: 'F. 木乃伊 / 古墓 / 封印者', groupEn: 'F. Mummy / Tomb / Sealed One', def: '第一识别是年幼王权被绷带和黄金提前封存的法老童。造型入口：过大的王冠、小型金饰、亚麻绷带、干瘦四肢和被礼仪抬高的正面姿态。母题：儿童身体承担不属于它的永恒工程。张力：可怜感必须被王权符号压住，避免可爱化。视觉证据：小权杖、护符、紧缠绷带、空洞眼神、石棺尺度。边界：避免普通儿童木乃伊或萌化法老。', defEn: 'First read: a child pharaoh whose young sovereignty is sealed early by bandage and gold. Styling entry: oversized crown, small gold ornaments, linen wraps, thin limbs, and ritual-raised frontality. Motif: a child body carrying an eternity project too large for it. Tension: pity must be pressed down by royal symbols, avoiding cuteness. Visual evidence: small scepter, amulets, tight wrappings, hollow eyes, and sarcophagus scale. Boundary: avoid generic child mummy or cute pharaoh.', eras: ancientEras, tags: ['mummy', 'pharaoh_child', 'wrapped'] },
  { id: 'museum_mummy_actor', name: '博物馆木乃伊演员', nameEn: 'Museum Mummy Actor', group: 'F. 木乃伊 / 古墓 / 封印者', groupEn: 'F. Mummy / Tomb / Sealed One', def: '第一识别是在博物馆展陈和表演职业之间制造木乃伊形象的人。造型入口：仿古绷带、展柜灯、讲解耳麦、半职业半扮演的站姿和被游客观看的疲惫。母题：死亡形象被现代展览消费。张力：他可能只是演员，也可能被展品气息侵蚀；重点在表演边界不稳。视觉证据：工牌、展柜反光、假旧绷带、后台水杯、游客距离。边界：避免真古墓怪物或普通cos。', defEn: 'First read: a person producing a mummy image between museum display and performance job. Styling entry: faux-aged bandages, display-case light, guide earpiece, half-professional half-performed stance, and fatigue from being watched by visitors. Motif: death image consumed by modern exhibition. Tension: he may only be an actor, or may be eroded by artifact aura; the unstable performance boundary matters. Visual evidence: badge, glass reflection, fake-aged wraps, backstage cup, and visitor distance. Boundary: avoid real tomb monster or generic cosplay.', ontologyLevel: 2, eras: modernEras, tags: ['museum', 'mummy', 'actor'] },
  { id: 'sealed_sarcophagus_bride', name: '石棺封印新娘', nameEn: 'Sarcophagus-Sealed Bride', group: 'F. 木乃伊 / 古墓 / 封印者', groupEn: 'F. Mummy / Tomb / Sealed One', def: '第一识别是婚礼身份被石棺封存的古墓新娘。造型入口：石棺边缘、白色或金色残纱、绷带下的首饰、被封印压住的手和像刚被打开的眼神。母题：婚约变成墓室契约。张力：她不是普通新娘，而是被物理封存和仪式债务锁住。视觉证据：石粉、封印纹、断裂花冠、手腕绷带、低位起身姿态。边界：避免甜美古风新娘。', defEn: 'First read: an ancient tomb bride whose bridal identity is sealed in a sarcophagus. Styling entry: sarcophagus edge, white or gold torn veil, jewelry under bandages, hands pressed by sealing, and eyes as if just opened. Motif: marriage turning into tomb contract. Tension: she is not a normal bride but locked by physical sealing and ritual debt. Visual evidence: stone dust, seal marks, broken flower crown, wrist bandages, and low rising posture. Boundary: avoid sweet period bride.', tags: ['sarcophagus', 'bride', 'mummy'] },
  { id: 'desert_tomb_thief_undead', name: '沙漠盗墓不死者', nameEn: 'Desert Tomb-Thief Undead', group: 'F. 木乃伊 / 古墓 / 封印者', groupEn: 'F. Mummy / Tomb / Sealed One', def: '第一识别是盗墓惩罚已经写进身体的沙漠不死者。造型入口：沙尘布巾、偷来的护符、干裂皮肤、背包、被诅咒拖慢的脚步。母题：贪婪被墓室规则反噬。张力：他不是冒险英雄，而是永远带着赃物和惩罚逃不出沙漠。视觉证据：破指南针、金片、绷带、沙粒附着、回头恐惧。边界：避免普通探险家或木乃伊怪。', defEn: 'First read: a desert undead whose body carries tomb-theft punishment. Styling entry: sand scarf, stolen amulet, cracked skin, pack, and curse-slowed steps. Motif: greed retaliated by tomb rules. Tension: he is not an adventure hero but someone forever carrying loot and punishment through desert. Visual evidence: broken compass, gold flakes, bandages, sand adhesion, and fearful backward glance. Boundary: avoid generic explorer or mummy monster.', tags: ['tomb_thief', 'undead', 'desert'] },
  { id: 'canopic_jar_priest', name: '卡诺匹斯罐祭司', nameEn: 'Canopic-Jar Priest', group: 'F. 木乃伊 / 古墓 / 封印者', groupEn: 'F. Mummy / Tomb / Sealed One', def: '第一识别是身体与内脏容器秩序绑定的古墓祭司。造型入口：卡诺匹斯罐、亚麻长袍、手托器皿、干燥脸部和不看观众而看容器的眼神。母题：身体被拆分后仍由仪式管理。张力：不要把内脏写成血腥，重点是容器、保存和职责。视觉证据：罐盖动物头、石台、护符、干手、慢而准确的搬运动作。边界：避免普通祭司或猎奇解剖。', defEn: 'First read: an ancient tomb priest bound to the order of organ vessels. Styling entry: canopic jars, linen robe, hands carrying vessels, dried face, and eyes looking at container rather than viewer. Motif: body managed by ritual even after division. Tension: do not make organs gory; focus on vessel, preservation, and duty. Visual evidence: animal-headed jar lids, stone table, amulets, dry hands, and slow precise carrying motion. Boundary: avoid generic priest or shock anatomy.', eras: ancientEras, tags: ['canopic_jar', 'priest', 'mummy'] },
  { id: 'curse_tablet_student', name: '诅咒石板学生', nameEn: 'Curse-Tablet Student', group: 'F. 木乃伊 / 古墓 / 封印者', groupEn: 'F. Mummy / Tomb / Sealed One', def: '第一识别是被一块古代诅咒石板牵连的现代学生。造型入口：校服或连帽衫、背包里露出的石板、指尖沙尘、熬夜眼和被古文字吸住注意力的姿态。母题：现代学习身体撞上古墓文本。张力：他不是考古学家，危险来自普通学生生活被文物规则侵入。视觉证据：图书馆灯、笔记、裂纹石板、手上灰尘、紧张低头。边界：避免魔法少年或完整探险剧情。', defEn: 'First read: a modern student implicated by an ancient curse tablet. Styling entry: school uniform or hoodie, tablet peeking from backpack, sandy fingertips, sleepless eyes, and posture absorbed by old writing. Motif: modern study body colliding with tomb text. Tension: they are not an archaeologist; danger comes from artifact rules invading ordinary student life. Visual evidence: library light, notes, cracked tablet, dust on hands, tense lowered head. Boundary: avoid magic student or full adventure plot.', ontologyLevel: 3, eras: modernEras, tags: ['curse_tablet', 'student', 'artifact'] },
  { id: 'gold_mask_revenant', name: '黄金面具还魂者', nameEn: 'Gold-Mask Revenant', group: 'F. 木乃伊 / 古墓 / 封印者', groupEn: 'F. Mummy / Tomb / Sealed One', def: '第一识别是被黄金面具重新定义脸部的还魂者。造型入口：金面具、暗眼孔、破损绷带、被面具重量压低的颈部和像从墓室光中转头的动作。母题：权力面具替代真实脸。张力：豪华感必须带着封存和窒息，不是华丽装饰。视觉证据：金箔裂痕、黑眼洞、亚麻层、僵硬脖颈、手扶面具边缘。边界：避免普通黄金战士。', defEn: 'First read: a revenant whose face is redefined by a gold mask. Styling entry: gold mask, dark eye holes, damaged wrappings, neck lowered by mask weight, and a turn from tomb light. Motif: power mask replacing true face. Tension: luxury must carry sealing and suffocation, not mere ornament. Visual evidence: cracked gold leaf, black eye holes, linen layers, stiff neck, and hand on mask edge. Boundary: avoid generic golden warrior.', tags: ['gold_mask', 'revenant', 'mummy'] },
  { id: 'tomb_dust_librarian', name: '墓尘图书管理员', nameEn: 'Tomb-Dust Librarian', group: 'F. 木乃伊 / 古墓 / 封印者', groupEn: 'F. Mummy / Tomb / Sealed One', def: '第一识别是管理墓室书卷、灰尘和禁书顺序的不死图书管理员。造型入口：灰尘外套、干手、卷轴柜、护目镜或细框眼镜和让人噤声的手势。母题：知识保存与尸体保存同构。张力：她不靠恐怖攻击，而靠索引、封存和禁止翻阅形成威严。视觉证据：书脊灰、封签、低声姿态、干裂指节、灯下尘粒。边界：避免普通图书管理员或法师。', defEn: 'First read: an undead librarian managing tomb scrolls, dust, and forbidden order. Styling entry: dust coat, dry hands, scroll cabinets, goggles or thin glasses, and a shushing gesture. Motif: preservation of knowledge mirroring preservation of bodies. Tension: she does not attack; authority comes from indexing, sealing, and forbidding access. Visual evidence: dusty spines, seals, low-voice posture, cracked knuckles, and dust in lamp light. Boundary: avoid generic librarian or wizard.', tags: ['tomb_dust', 'librarian', 'archive'] },

  { id: 'lich_professor', name: '巫妖教授', nameEn: 'Lich Professor', group: 'G. 巫妖 / 死灵法 / 永生代价', groupEn: 'G. Lich / Necromancy / Cost of Immortality', def: '第一识别是把永生研究变成学术职位的巫妖教授。造型入口：旧学袍、骨化手指、讲义、眼眶蓝火或空洞、像上课一样解释死亡的姿态。母题：知识追求越过生命边界。张力：他不是狂乱法师，而是用课堂秩序讲述最不该被教的东西。视觉证据：黑板符号、粉笔灰、命匣暗示、干瘦脸、指向公式的骨手。边界：避免普通魔法老师。', defEn: 'First read: a lich professor who has turned immortality research into an academic post. Styling entry: old robe, ossified fingers, lecture notes, blue fire or hollow sockets, and a posture explaining death like a class. Motif: knowledge pursuit crossing life boundary. Tension: he is not a mad wizard but teaches what should not be taught through classroom order. Visual evidence: blackboard signs, chalk dust, phylactery hint, gaunt face, and bone hand pointing at formula. Boundary: avoid generic magic teacher.', tags: ['lich', 'professor', 'necromancy'] },
  { id: 'necromancer_doctor', name: '死灵医生', nameEn: 'Necromancer Doctor', group: 'G. 巫妖 / 死灵法 / 永生代价', groupEn: 'G. Lich / Necromancy / Cost of Immortality', def: '第一识别是把医学和死灵术缝合在一起的医生。造型入口：白大褂、黑色缝线、骨针、病历、冷静触诊和像判断生命可否重启的眼神。母题：治疗欲望越界成复活控制。张力：他不应像血腥怪医，重点是临床流程与禁忌法术的并列。视觉证据：听诊器、符文病历、手套、缝合工具、病床边低头。边界：避免普通医生或屠夫。', defEn: 'First read: a doctor stitching medicine and necromancy together. Styling entry: lab coat, black sutures, bone needle, charts, calm palpation, and eyes judging whether life can reboot. Motif: healing desire crossing into resurrection control. Tension: he should not be a gore mad doctor; focus on clinical process beside forbidden spellcraft. Visual evidence: stethoscope, rune charts, gloves, suture tools, and lowered head at bedside. Boundary: avoid generic doctor or butcher.', tags: ['necromancer', 'doctor', 'medicine'] },
  { id: 'soul_jar_accountant', name: '魂罐会计', nameEn: 'Soul-Jar Accountant', group: 'G. 巫妖 / 死灵法 / 永生代价', groupEn: 'G. Lich / Necromancy / Cost of Immortality', def: '第一识别是把灵魂容器当成账目管理的会计。造型入口：账本、编号魂罐、袖套、干燥手指和计算时不带情绪的侧脸。母题：永生资源被行政化。张力：恐怖来自分类和余额，而不是法术爆炸。视觉证据：玻璃罐微光、标签、算盘或计算器、密集表格、护住罐子的手。边界：避免普通会计或魔法商人。', defEn: 'First read: an accountant managing soul jars as accounts. Styling entry: ledger, numbered soul jars, sleeve guards, dry fingers, and an emotionless profile while calculating. Motif: immortality resources becoming administration. Tension: horror comes from classification and balance, not spell explosions. Visual evidence: faint glowing jars, labels, abacus or calculator, dense tables, and hands protecting a jar. Boundary: avoid generic accountant or magic merchant.', tags: ['soul_jar', 'accountant', 'admin'] },
  { id: 'grave_contract_lawyer', name: '墓契律师', nameEn: 'Grave-Contract Lawyer', group: 'G. 巫妖 / 死灵法 / 永生代价', groupEn: 'G. Lich / Necromancy / Cost of Immortality', def: '第一识别是专门处理墓地、死后债务和复生条款的律师。造型入口：黑色公文包、墓契、蜡封、冷静眼镜和像在墓碑前谈判的站姿。母题：死亡被合同化。张力：他不是法师，危险在于每句话都能改变尸体归属。视觉证据：契约纸、钢笔、印章、墓地地契、低声递文件的手。边界：避免普通律师或阴谋反派。', defEn: 'First read: a lawyer handling graves, postmortem debt, and resurrection clauses. Styling entry: black briefcase, grave contracts, wax seals, calm glasses, and a posture negotiating before tombstones. Motif: death contractualized. Tension: he is not a wizard; danger lies in sentences that alter corpse ownership. Visual evidence: contract paper, pen, seal, cemetery deed, and a hand quietly offering documents. Boundary: avoid generic lawyer or conspiracy villain.', tags: ['grave_contract', 'lawyer', 'death_law'] },
  { id: 'immortality_failed_alchemist', name: '永生失败炼金术士', nameEn: 'Failed-Immortality Alchemist', group: 'G. 巫妖 / 死灵法 / 永生代价', groupEn: 'G. Lich / Necromancy / Cost of Immortality', def: '第一识别是永生实验没有成功也没有完全失败的炼金术士。造型入口：烧焦袖口、药剂污渍、半腐半保存皮肤、玻璃瓶和不停检查自己手背的动作。母题：永生追求留下中间状态。张力：他不是成功巫妖，而是被实验结果困在不可公布的身体里。视觉证据：失败笔记、裂瓶、金属味污渍、眼下疲惫、遮盖身体的围裙。边界：避免普通炼金师或疯狂科学家。', defEn: 'First read: an alchemist whose immortality experiment neither succeeded nor fully failed. Styling entry: burnt cuffs, potion stains, half-decayed half-preserved skin, glass bottles, and constant checking of the back of his hand. Motif: the pursuit of immortality leaving an in-between state. Tension: he is not a successful lich, but trapped in an unpublished body result. Visual evidence: failed notes, cracked vials, metallic stains, tired eyes, and apron hiding the body. Boundary: avoid generic alchemist or mad scientist.', tags: ['alchemy', 'immortality', 'failed'] },
  { id: 'bone_servant_tailor', name: '骨仆裁缝', nameEn: 'Bone-Servant Tailor', group: 'G. 巫妖 / 死灵法 / 永生代价', groupEn: 'G. Lich / Necromancy / Cost of Immortality', def: '第一识别是为死者、巫妖或骨仆修补服制的裁缝。造型入口：针线、骨尺、黑围裙、骨手或极瘦手指和把衣服量在非人肩线上的动作。母题：服装工艺服务死亡等级。张力：他不需要像怪物，技术细节要证明他熟悉尸骨比例。视觉证据：骨针、旧布料、粉笔线、骷髅假台、沉默专注。边界：避免普通裁缝或恐怖工匠。', defEn: 'First read: a tailor repairing garments for the dead, liches, or bone servants. Styling entry: needle, bone ruler, black apron, bone hand or extremely thin fingers, and measuring cloth across non-human shoulders. Motif: garment craft serving death hierarchy. Tension: he need not look monstrous; technical details prove familiarity with skeletal proportions. Visual evidence: bone needle, old fabric, chalk lines, skeleton dress form, and silent focus. Boundary: avoid generic tailor or horror craftsman.', tags: ['bone_servant', 'tailor', 'craft'] },
  { id: 'death_magic_schoolgirl', name: '死灵术女学生', nameEn: 'Death-Magic Schoolgirl', group: 'G. 巫妖 / 死灵法 / 永生代价', groupEn: 'G. Lich / Necromancy / Cost of Immortality', def: '第一识别是在校园外壳下学习死亡术式的成年女学生形象。造型入口：深色校服、骨质笔记本、压低的书包、符号袖口和不该出现在课堂里的冷静眼神。母题：学习制度接入禁忌知识。张力：保持成人边界，重点是学生身份和死灵知识冲突，不是少女化卖点。视觉证据：咒文笔记、骨笔、黑袜、课桌阴影、像背公式一样背咒语的嘴。边界：避免未成年暧昧或普通魔法少女。', defEn: 'First read: an adult schoolgirl-coded figure studying death magic under an academic shell. Styling entry: dark uniform, bone notebook, lowered schoolbag, symbolic cuffs, and calm eyes that should not belong in class. Motif: education system connected to forbidden knowledge. Tension: keep adult boundary; focus on conflict between student identity and necromantic study, not girl fetish. Visual evidence: spell notes, bone pen, black socks, desk shadow, and lips reciting curses like formulas. Boundary: avoid underage ambiguity or generic magical girl.', eras: modernEras, tags: ['death_magic', 'student', 'school'] },
  { id: 'phylactery_bride', name: '命匣新娘', nameEn: 'Phylactery Bride', group: 'G. 巫妖 / 死灵法 / 永生代价', groupEn: 'G. Lich / Necromancy / Cost of Immortality', def: '第一识别是婚礼身份与命匣绑定的诅咒新娘。造型入口：胸前或手中命匣、婚纱与黑色封签、苍白嘴唇和像保护心脏一样保护容器的手。母题：爱情誓言被永生容器替换。张力：她不是普通新娘，真正的身体中心不在肉身而在命匣。视觉证据：小匣、锁链、白纱下黑符、冷静护持姿态、空洞眼神。边界：避免甜美婚礼或普通巫妖。', defEn: 'First read: a cursed bride whose bridal identity is bound to a phylactery. Styling entry: phylactery on chest or in hand, bridal gown with black seals, pale lips, and hands protecting the container like a heart. Motif: love vow replaced by immortality vessel. Tension: she is not a normal bride; the true body center is not flesh but the phylactery. Visual evidence: small box, chain, black sigils under white veil, calm guarding pose, and hollow gaze. Boundary: avoid sweet wedding or generic lich.', tags: ['phylactery', 'bride', 'lich'] },
  { id: 'undead_lab_assistant', name: '不死实验助手', nameEn: 'Undead Lab Assistant', group: 'G. 巫妖 / 死灵法 / 永生代价', groupEn: 'G. Lich / Necromancy / Cost of Immortality', def: '第一识别是已经死过却仍在实验室按流程工作的助手。造型入口：实验服、编号腕带、苍白皮肤、试管盘和动作过于稳定的递交姿态。母题：实验对象与实验人员身份重叠。张力：他可能是助手，也可能是研究成果；不确定性应落在身体细节和编号上。视觉证据：标本柜、手套、缝线、冷光、无表情记录动作。边界：避免普通研究员或丧尸怪。', defEn: 'First read: an assistant who has already died but still follows lab procedure. Styling entry: lab coat, numbered wristband, pale skin, test-tube tray, and a handoff posture too stable. Motif: overlap between experiment subject and experiment staff. Tension: he may be assistant or result; ambiguity lands in body detail and numbering. Visual evidence: specimen cabinet, gloves, sutures, cold light, and expressionless recording motion. Boundary: avoid generic researcher or zombie monster.', eras: modernEras, tags: ['undead', 'lab_assistant', 'experiment'] },
  { id: 'soul_tax_collector', name: '灵魂税吏', nameEn: 'Soul-Tax Collector', group: 'G. 巫妖 / 死灵法 / 永生代价', groupEn: 'G. Lich / Necromancy / Cost of Immortality', def: '第一识别是把灵魂当作税目征收的死灵官吏。造型入口：账册、印章、暗色制服、收据和像检查欠税一样检查人脸的目光。母题：死后世界的行政暴力。张力：他不靠邪恶表情，压迫感来自规章、编号和不可商量的手续。视觉证据：灵魂收据、黑章、袖章、排队亡灵暗示、递出文件的手。边界：避免普通税务员或冥界魔王。', defEn: 'First read: a necromantic official collecting souls as tax items. Styling entry: ledger, stamp, dark uniform, receipts, and a gaze inspecting faces like unpaid accounts. Motif: administrative violence of the afterlife. Tension: he does not need evil expression; pressure comes from rules, numbers, and nonnegotiable procedure. Visual evidence: soul receipt, black seal, armband, implied queue of dead, and hand offering documents. Boundary: avoid generic tax officer or underworld king.', tags: ['soul_tax', 'collector', 'bureaucracy'] },

  { id: 'immortal_butler', name: '不死管家', nameEn: 'Immortal Butler', group: 'H. 不死仆从 / 家宅亡灵', groupEn: 'H. Undead Servant / Domestic Dead', def: '第一识别是服侍过数代主人、礼仪比身体更不死的管家。造型入口：黑燕尾服、白手套、银托盘、干枯脸部和在废宅里仍保持服务角度的身体。母题：服务秩序比家族生命更长。张力：他不是恐怖怪物，而是用过度准确的礼貌让人不安。视觉证据：钥匙、怀表、旧餐厅、无声开门、像已经重复百年的鞠躬。边界：避免普通老管家。', defEn: 'First read: a butler who has served generations, with etiquette more immortal than the body. Styling entry: black tailcoat, white gloves, silver tray, dried face, and service angle maintained inside a ruined house. Motif: service order outliving family life. Tension: he is not a horror monster; excessive precision of courtesy unsettles. Visual evidence: keys, pocket watch, old dining room, silent door opening, and a bow repeated for a century. Boundary: avoid generic old butler.', tags: ['immortal', 'butler', 'estate'] },
  { id: 'dead_housemaid', name: '死者女仆', nameEn: 'Dead Housemaid', group: 'H. 不死仆从 / 家宅亡灵', groupEn: 'H. Undead Servant / Domestic Dead', def: '第一识别是已经死亡却仍执行家务流程的女仆。造型入口：黑白围裙、冷白手背、抹布、低头站位和像听候吩咐却没人会再叫她的空等待。母题：劳动角色在死后残留。张力：不要写成可爱女仆，疲惫、阶级和重复动作是核心。视觉证据：磨旧围裙、湿抹布、扫帚、半透明袖口、避开视线的表情。边界：避免萌系女仆或随机幽灵。', defEn: 'First read: a dead maid still executing household routine. Styling entry: black-white apron, cold white hands, rag, lowered service position, and empty waiting for orders no one gives. Motif: labor role remaining after death. Tension: do not make her cute; fatigue, class, and repetition are core. Visual evidence: worn apron, damp rag, broom, translucent cuffs, and expression avoiding eye contact. Boundary: avoid moe maid or random ghost.', tags: ['dead', 'housemaid', 'labor'] },
  { id: 'ghost_nanny', name: '幽灵保姆', nameEn: 'Ghost Nanny', group: 'H. 不死仆从 / 家宅亡灵', groupEn: 'H. Undead Servant / Domestic Dead', def: '第一识别是照护职责没有随身体消失的幽灵保姆。造型入口：旧围裙、摇篮边姿态、半透明手、轻声哄睡的嘴型和看不见孩子的怀抱空间。母题：照护动作在死亡后继续。张力：温柔和阴冷必须并存，不要变成恐怖抓娃娃。视觉证据：奶瓶、旧童毯、低头微笑、空抱姿势、夜间窗光。边界：避免普通保姆或惊悚女鬼。', defEn: 'First read: a ghost nanny whose care duty did not disappear with the body. Styling entry: old apron, cradle-side posture, translucent hands, mouth shape of lullaby, and arms holding an unseen child. Motif: caregiving motion continuing after death. Tension: tenderness and coldness must coexist; do not turn her into a baby-snatching horror. Visual evidence: bottle, old blanket, lowered smile, empty holding pose, and night window light. Boundary: avoid generic nanny or jump-scare ghost.', tags: ['ghost', 'nanny', 'care'] },
  { id: 'graveyard_gardener', name: '墓园园丁', nameEn: 'Graveyard Gardener', group: 'H. 不死仆从 / 家宅亡灵', groupEn: 'H. Undead Servant / Domestic Dead', def: '第一识别是在墓碑和花草之间维持秩序的墓园园丁。造型入口：泥手套、剪枝剪、旧围裙、墓碑旁弯腰和像照顾活人一样照顾死者名字的表情。母题：维护死亡空间的劳动者。张力：他不是守墓怪物，身份来自工具、植物和安静日常。视觉证据：剪下枯枝、花盆、墓碑清洁痕、泥靴、低声工作。边界：避免普通农夫或恐怖守墓人。', defEn: 'First read: a cemetery gardener maintaining order between graves and plants. Styling entry: muddy gloves, pruning shears, old apron, bending beside a stone, and a face caring for dead names like living people. Motif: laborer maintaining death space. Tension: he is not a grave monster; identity comes from tools, plants, and quiet daily work. Visual evidence: cut dead branches, flower pots, cleaned stone marks, muddy boots, and low-voice work. Boundary: avoid generic farmer or horror gravedigger.', ontologyLevel: 2, eras: modernEras, tags: ['graveyard', 'gardener', 'labor'] },
  { id: 'ancestral_cook', name: '祖宅亡灵厨娘', nameEn: 'Ancestral Ghost Cook', group: 'H. 不死仆从 / 家宅亡灵', groupEn: 'H. Undead Servant / Domestic Dead', def: '第一识别是在祖宅厨房里继续准备早已无人享用食物的亡灵厨娘。造型入口：旧围裙、菜刀、锅炉蒸汽、半透明手腕和像记得每个家族口味的低头专注。母题：家族日常被亡灵劳动维持。张力：食物气味和死亡冷感并置。视觉证据：铜锅、旧菜谱、火光、冷脸、端盘但餐桌空无一人。边界：避免普通厨娘或食人恐怖。', defEn: 'First read: an ancestral ghost cook still preparing food no one eats in the old kitchen. Styling entry: old apron, kitchen knife, boiler steam, translucent wrists, and lowered focus as if remembering every family taste. Motif: family daily life maintained by ghost labor. Tension: food warmth and death coldness coexist. Visual evidence: copper pot, old recipe, firelight, cold face, and tray carried to an empty table. Boundary: avoid generic cook or cannibal horror.', tags: ['ghost', 'cook', 'ancestral_house'] },
  { id: 'coffin_room_servant', name: '棺材房侍者', nameEn: 'Coffin-Room Servant', group: 'H. 不死仆从 / 家宅亡灵', groupEn: 'H. Undead Servant / Domestic Dead', def: '第一识别是负责整理棺材房、鲜花和访客秩序的侍者。造型入口：黑色制服、白花、棺木边缘、低声引导手势和像不打扰死者的脚步。母题：死亡被服务业流程管理。张力：他是否活着不必明说，身体安静到近乎没有体温。视觉证据：花篮、手套、访客登记、低头让路、棺盖反光。边界：避免普通服务员或吸血鬼管家。', defEn: 'First read: a servant arranging coffin room, flowers, and visitor order. Styling entry: black uniform, white flowers, coffin edge, quiet guiding gesture, and steps that do not disturb the dead. Motif: death managed by service procedure. Tension: whether he is alive need not be explicit; the body is quiet almost without temperature. Visual evidence: flower basket, gloves, visitor register, bowed passage-making, and coffin-lid reflection. Boundary: avoid generic waiter or vampire butler.', ontologyLevel: 2, eras: modernEras, tags: ['coffin_room', 'servant', 'funeral'] },
  { id: 'widow_house_driver', name: '寡妇宅司机', nameEn: 'Widow-House Driver', group: 'H. 不死仆从 / 家宅亡灵', groupEn: 'H. Undead Servant / Domestic Dead', def: '第一识别是永远停在寡妇宅门口等待命令的司机。造型入口：黑色司机制服、旧车钥匙、雨夜车灯、白手套和从后视镜里看人的沉默眼神。母题：忠诚停在一段丧偶时间里。张力：他不像活人也不像鬼，像一项永远未取消的服务。视觉证据：车门、伞、老式帽檐、熄不掉的车灯、僵硬等待姿态。边界：避免普通司机或黑帮车手。', defEn: 'First read: a driver forever waiting outside a widow house for orders. Styling entry: black chauffeur uniform, old car keys, rainy headlights, white gloves, and silent eyes seen in the rearview mirror. Motif: loyalty parked in a widowed time. Tension: he reads neither fully alive nor ghost, but like a service never cancelled. Visual evidence: car door, umbrella, old cap brim, headlights that will not go out, and stiff waiting posture. Boundary: avoid generic driver or gangster chauffeur.', eras: modernEras, tags: ['driver', 'widow_house', 'servant'] },
  { id: 'spirit_laundry_woman', name: '亡灵洗衣女', nameEn: 'Spirit Laundry Woman', group: 'H. 不死仆从 / 家宅亡灵', groupEn: 'H. Undead Servant / Domestic Dead', def: '第一识别是一直清洗丧服、床单和家族污渍的亡灵洗衣女。造型入口：湿袖口、洗衣盆、白布、冷水、弯腰搓洗动作和被蒸汽遮住的脸。母题：家族罪责被日常劳动反复清洗。张力：她不是恐怖角色，压迫感来自永远洗不干净。视觉证据：水盆、肥皂、发白手指、晾衣绳、低头重复动作。边界：避免普通洗衣工或水鬼。', defEn: 'First read: a spirit laundry woman endlessly washing mourning clothes, sheets, and family stains. Styling entry: wet cuffs, wash basin, white cloth, cold water, scrubbing bend, and a face hidden by steam. Motif: family guilt repeatedly washed through daily labor. Tension: she is not a horror figure; pressure comes from never getting it clean. Visual evidence: basin, soap, whitened fingers, clothesline, and lowered repetitive motion. Boundary: avoid generic washerwoman or water ghost.', tags: ['spirit', 'laundry', 'labor'] },
  { id: 'dead_family_doctor', name: '死去的家庭医生', nameEn: 'Dead Family Doctor', group: 'H. 不死仆从 / 家宅亡灵', groupEn: 'H. Undead Servant / Domestic Dead', def: '第一识别是去世后仍在家族宅邸里履行诊疗职责的家庭医生。造型入口：旧医生包、听诊器、黑色三件套、苍白脸和像给不存在病人把脉的手。母题：家族照护制度变成亡灵惯性。张力：他不是现代医院医生，而是宅邸里保守秘密的人。视觉证据：药瓶、病历、怀表、低声诊断、床边阴影。边界：避免普通医生或死灵法师。', defEn: 'First read: a deceased family doctor still performing care duties inside the manor. Styling entry: old doctor bag, stethoscope, black three-piece suit, pale face, and hands taking the pulse of an absent patient. Motif: family care system becoming ghost inertia. Tension: he is not a modern hospital doctor but keeper of household secrets. Visual evidence: medicine bottles, records, pocket watch, quiet diagnosis, and bedside shadow. Boundary: avoid generic doctor or necromancer.', eras: modernEras, tags: ['dead_doctor', 'family', 'estate'] },
  { id: 'haunted_estate_child', name: '鬼庄园孩子', nameEn: 'Haunted-Estate Child', group: 'H. 不死仆从 / 家宅亡灵', groupEn: 'H. Undead Servant / Domestic Dead', def: '第一识别是被庄园规矩和幽灵气氛养大的孩子形象。造型入口：旧童装、过大的钥匙、冷白袜、门后探出的身体和像已经学会不出声的眼神。母题：儿童身份被宅邸秩序吞掉。张力：保持非暧昧、非可爱化，重点是空间纪律和孤独。视觉证据：玩具、走廊、旧画像、安静脚尖、手握门框。边界：避免恐怖小孩套路或普通贵族儿童。', defEn: 'First read: a child figure raised by estate rules and ghost atmosphere. Styling entry: old child clothes, oversized key, cold white socks, body peeking from behind a door, and eyes already trained not to make sound. Motif: childhood swallowed by household order. Tension: keep it non-seductive and non-cute; focus on spatial discipline and loneliness. Visual evidence: toy, corridor, old portrait, quiet toes, and hand on doorframe. Boundary: avoid horror-child cliche or generic noble child.', tags: ['haunted_estate', 'child', 'house'] },

  { id: 'uploaded_dead_influencer', name: '上传死者网红', nameEn: 'Uploaded Dead Influencer', group: 'I. 现代亡灵 / 数字死者', groupEn: 'I. Modern Undead / Digital Dead', def: '第一识别是死后仍被平台算法发布、维护和观看的网红形象。造型入口：环形灯、过度平滑脸、纪念账号界面、冻结微笑和像等待评论刷新一样的眼神。母题：死亡被社交媒体延迟。张力：她不是活着的博主，而是被旧素材、AI补帧和粉丝记忆拼出来的公众身体。视觉证据：手机支架、黑色纪念丝带、屏幕反光、完美但空的自拍姿态。边界：避免普通网红。', defEn: 'First read: an influencer still posted, maintained, and watched by platform algorithms after death. Styling entry: ring light, over-smoothed face, memorial account interface, frozen smile, and eyes waiting for comments to refresh. Motif: death delayed by social media. Tension: she is not a living blogger but a public body assembled from old footage, AI interpolation, and fan memory. Visual evidence: phone stand, black memorial ribbon, screen reflection, perfect but empty selfie posture. Boundary: avoid generic influencer.', eras: modernEras, tags: ['uploaded_dead', 'influencer', 'platform'] },
  { id: 'cloud_memorial_girl', name: '云纪念馆女孩', nameEn: 'Cloud-Memorial Girl', group: 'I. 现代亡灵 / 数字死者', groupEn: 'I. Modern Undead / Digital Dead', def: '第一识别是存在于云纪念馆界面、照片和悼念留言之间的女孩形象。造型入口：柔光头像、纪念页边框、半透明身体边缘、留言气泡和像从旧照片里看人的眼神。母题：哀悼被平台空间化。张力：她不应变成赛博幽灵怪，而是由家人选择的照片和文字维持存在。视觉证据：云端相册、蜡烛图标、旧照片色、安静正面脸。边界：避免普通少女或科幻AI。', defEn: 'First read: a girl existing between cloud memorial interface, photos, and mourning messages. Styling entry: soft avatar light, memorial-page frame, translucent body edge, message bubbles, and eyes looking out from old photos. Motif: mourning spatialized by platform. Tension: she should not become a cyber ghost monster; existence is maintained by family-chosen images and text. Visual evidence: cloud album, candle icon, old-photo color, and quiet frontal face. Boundary: avoid generic girl or sci-fi AI.', eras: modernEras, tags: ['cloud_memorial', 'digital_dead', 'girl'] },
  { id: 'ai_ghost_boyfriend', name: 'AI幽灵男友', nameEn: 'AI Ghost Boyfriend', group: 'I. 现代亡灵 / 数字死者', groupEn: 'I. Modern Undead / Digital Dead', def: '第一识别是由聊天记录、语音样本和遗照训练出的AI幽灵男友。造型入口：手机冷光、过度温柔表情、半透明头像边缘、耳机和像永远正在回复的眼神。母题：亲密关系被数据模型复活。张力：他不是机器人男友，而是一个被哀悼需求维持的数字亡灵。视觉证据：聊天气泡、旧语音波形、黑色纪念头像框、屏幕反射在脸上。边界：避免普通恋人或实体仿生人。', defEn: 'First read: an AI ghost boyfriend trained from chat logs, voice samples, and memorial photos. Styling entry: phone glow, excessively gentle expression, translucent avatar edge, earbuds, and eyes as if always replying. Motif: intimacy resurrected by data model. Tension: he is not a robot boyfriend but a digital dead sustained by mourning need. Visual evidence: chat bubbles, old voice waveform, black memorial avatar frame, and screen reflection on face. Boundary: avoid generic lover or physical android.', eras: futureEras, tags: ['ai_ghost', 'boyfriend', 'digital'] },
  { id: 'dead_streamer_avatar', name: '死后直播化身', nameEn: 'Posthumous Streamer Avatar', group: 'I. 现代亡灵 / 数字死者', groupEn: 'I. Modern Undead / Digital Dead', def: '第一识别是主播死后仍在直播界面中运营的化身。造型入口：虚拟皮套、暂停的表情帧、直播弹幕、纪念黑边和像被程序驱动的挥手动作。母题：表演人格脱离生物身体继续营业。张力：可爱或炫酷外观下必须有死亡缺席感。视觉证据：弹幕悼念、模型骨骼绑定痕迹、空房间麦克风、循环表情。边界：避免普通VTuber或机器人。', defEn: 'First read: an avatar still operating in stream interface after the streamer has died. Styling entry: virtual model, paused expression frame, chat overlay, memorial black border, and a wave driven by program. Motif: performance persona continuing business after biological body is gone. Tension: cute or cool exterior must carry death absence. Visual evidence: memorial chat, rigging traces, empty-room microphone, and looping expression. Boundary: avoid generic VTuber or robot.', eras: modernEras, tags: ['posthumous', 'streamer', 'avatar'] },
  { id: 'voicemail_spirit_mother', name: '语音信箱亡母', nameEn: 'Voicemail-Spirit Mother', group: 'I. 现代亡灵 / 数字死者', groupEn: 'I. Modern Undead / Digital Dead', def: '第一识别是从语音信箱和旧手机里残留的母亲亡灵。造型入口：手机听筒、温柔但断续的嘴型、家居外套、半透明手和像正在留言“记得吃饭”的姿态。母题：照护声音在死亡后继续循环。张力：她不是恐怖电话鬼，而是亲密日常的残响。视觉证据：旧手机、语音波形、厨房光、微笑停顿、听筒旁的泪痕。边界：避免普通母亲或惊悚来电。', defEn: 'First read: a mother spirit remaining in voicemail and old phones. Styling entry: phone receiver, gentle but broken mouth shape, house cardigan, translucent hands, and posture leaving a message like "remember to eat." Motif: caregiving voice looping after death. Tension: she is not a horror phone ghost but residue of intimate daily care. Visual evidence: old phone, waveform, kitchen light, paused smile, and tear near receiver. Boundary: avoid generic mother or jump-scare call.', eras: modernEras, tags: ['voicemail', 'mother', 'spirit'] },
  { id: 'deepfake_revenant_actor', name: '深伪还魂演员', nameEn: 'Deepfake Revenant Actor', group: 'I. 现代亡灵 / 数字死者', groupEn: 'I. Modern Undead / Digital Dead', def: '第一识别是死后仍被深伪技术放回银幕的演员。造型入口：旧明星脸、数字接缝、片场服装、过于平滑的皮肤和表情延迟。母题：影像工业复活表演资产。张力：他不是本人，也不是普通AI角色，而是被版权、怀旧和技术拼接的还魂形象。视觉证据：面部边缘轻微错位、片场灯、替身身体、合成眼神、合同文件。边界：避免复制真实名人。', defEn: 'First read: an actor returned to screen after death by deepfake technology. Styling entry: old star-like face, digital seams, set costume, too-smooth skin, and delayed expression. Motif: image industry resurrecting performance asset. Tension: he is neither the person nor generic AI character, but a revenant assembled by rights, nostalgia, and technology. Visual evidence: slight facial edge mismatch, set lights, double body, synthetic gaze, and contract papers. Boundary: avoid copying real celebrities.', eras: modernEras, tags: ['deepfake', 'revenant', 'actor'], forbids: ['复制真实名人脸'] },
  { id: 'memory_card_ghost', name: '存储卡幽灵', nameEn: 'Memory-Card Ghost', group: 'I. 现代亡灵 / 数字死者', groupEn: 'I. Modern Undead / Digital Dead', def: '第一识别是被困在损坏存储卡影像里的幽灵。造型入口：低清像素、照片边缘损坏、卡槽、半透明身体块和像加载失败一样停顿的姿态。母题：记忆介质变成灵体容器。张力：不要变成纯故障图案，必须仍有一个可读人物被数据损坏。视觉证据：SD卡、相机屏、坏块、断裂轮廓、旧照片色。边界：避免普通数码故障或实体鬼怪。', defEn: 'First read: a ghost trapped in corrupted memory-card footage. Styling entry: low-res pixels, damaged photo edges, card slot, translucent body blocks, and a posture paused like failed loading. Motif: memory medium as spirit container. Tension: do not become pure glitch pattern; keep a readable person damaged by data. Visual evidence: SD card, camera screen, bad sectors, broken outline, old-photo color. Boundary: avoid generic digital glitch or physical ghost monster.', eras: modernEras, tags: ['memory_card', 'ghost', 'data'] },
  { id: 'funeral_livestream_host', name: '葬礼直播主持', nameEn: 'Funeral Livestream Host', group: 'I. 现代亡灵 / 数字死者', groupEn: 'I. Modern Undead / Digital Dead', def: '第一识别是把葬礼转成线上观看流程的直播主持。造型入口：黑色正装、领夹麦、直播架、悼念花和压低情绪的职业微笑。母题：死亡仪式进入远程媒介。张力：他不是亡灵本体，但站在生者、死者和屏幕观众之间。视觉证据：直播屏、弹幕悼词、花圈、手卡、克制手势。边界：避免普通主持人或网红。', defEn: 'First read: a host converting funeral into livestream procedure. Styling entry: black formalwear, lapel mic, streaming rig, condolence flowers, and a professional smile with emotion lowered. Motif: death ritual entering remote media. Tension: he is not undead himself, but stands between living, dead, and screen audience. Visual evidence: livestream screen, condolence chat, wreath, cue cards, and restrained hand gestures. Boundary: avoid generic host or influencer.', ontologyLevel: 1, eras: modernEras, tags: ['funeral', 'livestream', 'host'] },
  { id: 'digital_afterlife_consultant', name: '数字来世顾问', nameEn: 'Digital Afterlife Consultant', group: 'I. 现代亡灵 / 数字死者', groupEn: 'I. Modern Undead / Digital Dead', def: '第一识别是向客户解释数据遗产、人格备份和数字来世服务的顾问。造型入口：平板、深色商务服、安抚手势、纪念界面和像谈保险一样谈永生的表情。母题：来世被产品化。张力：他不必超自然，冷静商业话术已经足够不安。视觉证据：服务合同、云端墓园界面、客户照片、柔和会议室光、过度专业的眼神。边界：避免普通销售或神职人员。', defEn: 'First read: a consultant explaining data inheritance, personality backup, and digital afterlife services. Styling entry: tablet, dark business wear, calming gesture, memorial interface, and an expression discussing immortality like insurance. Motif: afterlife productized. Tension: he need not be supernatural; calm commercial language is unsettling enough. Visual evidence: service contract, cloud cemetery UI, client photos, soft meeting-room light, and overly professional eyes. Boundary: avoid generic salesperson or priest.', ontologyLevel: 2, eras: futureEras, tags: ['digital_afterlife', 'consultant', 'service'] },
  { id: 'expired_account_saint', name: '过期账号圣徒', nameEn: 'Expired-Account Saint', group: 'I. 现代亡灵 / 数字死者', groupEn: 'I. Modern Undead / Digital Dead', def: '第一识别是被注销、纪念和粉丝转发共同神圣化的过期账号圣徒。造型入口：灰掉的头像框、旧用户名、屏幕光环、半透明脸和像接受线上献花的静止姿态。母题：平台遗留物被民间崇拜化。张力：神圣感来自界面和群体记忆，不是真宗教神迹。视觉证据：失效链接、纪念贴、屏幕边框、像素光、被留言围住的正面性。边界：避免真实宗教圣徒或普通网红。', defEn: 'First read: an expired account sanctified by deletion, memorialization, and fan reposts. Styling entry: grayed avatar frame, old username, screen halo, translucent face, and still posture receiving online flowers. Motif: platform residue becoming folk devotion. Tension: holiness comes from interface and group memory, not real religious miracle. Visual evidence: dead links, memorial posts, screen border, pixel glow, and frontality surrounded by comments. Boundary: avoid real religious saint or generic influencer.', eras: modernEras, tags: ['expired_account', 'saint', 'digital_dead'] },

  { id: 'possessed_bride', name: '附身新娘', nameEn: 'Possessed Bride', group: 'J. 轮回 / 附身 / 借尸还魂', groupEn: 'J. Reincarnation / Possession / Returned Body', def: '第一识别是婚礼身体被另一个意志临时占据的附身新娘。造型入口：白纱、忽然变冷的眼神、手指姿势不属于本人、花束下垂和像听见体内声音的侧头。母题：仪式中心被外来灵魂接管。张力：不是恐怖乱叫，而是人格不一致的细节。视觉证据：错位微笑、发抖手套、婚戒、镜中表情不同、身体突然静止。边界：避免普通新娘或驱魔场面。', defEn: 'First read: a bride whose wedding body is temporarily occupied by another will. Styling entry: white veil, suddenly cold eyes, fingers shaped unlike herself, lowered bouquet, and head tilt as if hearing an inner voice. Motif: ritual center taken over by an outside soul. Tension: not screaming horror, but details of inconsistent personhood. Visual evidence: mismatched smile, trembling gloves, ring, different mirror expression, and sudden stillness. Boundary: avoid generic bride or exorcism scene.', tags: ['possession', 'bride', 'wedding'] },
  { id: 'reincarnated_queen_child', name: '转生女王儿童', nameEn: 'Reincarnated Queen Child', group: 'J. 轮回 / 附身 / 借尸还魂', groupEn: 'J. Reincarnation / Possession / Returned Body', def: '第一识别是儿童身体里带着前世女王记忆的转生者。造型入口：过小身体、过成熟目光、旧王室手势、玩具与权杖感物件并置。母题：身份年龄与身体年龄断裂。张力：保持非暧昧、非可爱化，重点是年龄错位和权力习惯残留。视觉证据：端坐姿态、旧戒指、书本、像发布命令的手势、孩子衣物里的威严。边界：避免普通神童或儿童女王cos。', defEn: 'First read: a reincarnated figure with a child body and a former queen memory. Styling entry: small body, overly mature gaze, old royal gestures, toys beside scepter-like objects. Motif: identity age split from body age. Tension: keep non-seductive and non-cute; focus on age dislocation and residue of authority habit. Visual evidence: seated posture, old ring, books, command-like hand gesture, and dignity inside child clothing. Boundary: avoid generic prodigy or child-queen cosplay.', tags: ['reincarnation', 'queen', 'child'] },
  { id: 'borrowed_body_detective', name: '借尸侦探', nameEn: 'Borrowed-Body Detective', group: 'J. 轮回 / 附身 / 借尸还魂', groupEn: 'J. Reincarnation / Possession / Returned Body', def: '第一识别是灵魂借用死者身体继续查案的侦探。造型入口：不合身外套、尸体编号痕迹、侦探笔记、动作和身体年龄不一致的步态。母题：调查欲望越过死亡和身体所有权。张力：他不是普通侦探，身体像临时租来的证据。视觉证据：手套、伤口遮盖、案卷、镜中陌生脸、检查自己手指的动作。边界：避免普通硬汉侦探或僵尸警察。', defEn: 'First read: a detective whose soul borrows a dead body to continue a case. Styling entry: ill-fitting coat, body ID traces, detective notes, and gait mismatching body age. Motif: investigative desire crossing death and body ownership. Tension: he is not a normal detective; the body feels like temporarily rented evidence. Visual evidence: gloves, covered wound, case files, unfamiliar face in mirror, and checking his own fingers. Boundary: avoid generic noir detective or zombie cop.', eras: modernEras, tags: ['borrowed_body', 'detective', 'possession'] },
  { id: 'spirit_medium_student', name: '灵媒学生', nameEn: 'Spirit-Medium Student', group: 'J. 轮回 / 附身 / 借尸还魂', groupEn: 'J. Reincarnation / Possession / Returned Body', def: '第一识别是在课堂、宿舍和灵体之间被迫开口的灵媒学生。造型入口：校服或学生外套、护符、疲惫眼神、记满陌生名字的笔记本和像被别人借用嗓子的嘴型。母题：学习生活被通灵能力打断。张力：他不是魔法主角，而是普通学生身体承受外来声音。视觉证据：耳塞、符纸、课堂桌面、颈部紧张、突然停笔的手。边界：避免普通占卜师或校园恋爱角色。', defEn: 'First read: a student forced to speak between classroom, dormitory, and spirits. Styling entry: school jacket, amulets, tired eyes, notebook full of unfamiliar names, and mouth shape as if someone borrows the voice. Motif: student life interrupted by mediumship. Tension: not a magical hero, but an ordinary student body carrying outside voices. Visual evidence: earplugs, talismans, classroom desk, tense throat, and hand suddenly stopping writing. Boundary: avoid generic fortune teller or school romance character.', eras: modernEras, tags: ['medium', 'student', 'spirit'] },
  { id: 'ancestor_possessed_son', name: '祖灵附身儿子', nameEn: 'Ancestor-Possessed Son', group: 'J. 轮回 / 附身 / 借尸还魂', groupEn: 'J. Reincarnation / Possession / Returned Body', def: '第一识别是身体仍是儿子、姿态却被祖灵接管的人。造型入口：现代衣物里突然出现的旧礼仪手势、家族香火、眼神变老、说话前停顿。母题：血缘记忆越过个人意志。张力：他不是普通孝子，而是身体成了家族祖先的临时容器。视觉证据：祖先牌位、香灰、紧绷肩颈、手势过于古老、家人回避的距离。边界：避免普通祭祖青年。', defEn: 'First read: a son whose body remains his own while posture is taken over by an ancestor spirit. Styling entry: old etiquette gestures inside modern clothing, family incense, aged gaze, and pauses before speaking. Motif: bloodline memory crossing personal will. Tension: he is not a filial son but a temporary vessel for family ancestors. Visual evidence: ancestral tablets, incense ash, tense neck and shoulders, gestures too old, and family keeping distance. Boundary: avoid generic ancestor-worship youth.', tags: ['ancestor', 'possession', 'family'] },
  { id: 'old_soul_schoolgirl', name: '老灵魂女学生', nameEn: 'Old-Soul Schoolgirl', group: 'J. 轮回 / 附身 / 借尸还魂', groupEn: 'J. Reincarnation / Possession / Returned Body', def: '第一识别是成年边界明确、学生外壳下带着前世疲惫的老灵魂女性。造型入口：校服式外套、过于沉静的眼神、旧式发夹、像看过很多年代的站姿。母题：年轻外观与过老心理时间错位。张力：重点是灵魂年龄压过青春符号，避免少女暧昧。视觉证据：旧书、复古笔记、克制表情、与同龄环境不合拍的身体距离。边界：避免普通学生或恋爱轻小说。', defEn: 'First read: an adult-boundary clear schoolgirl-coded woman carrying past-life fatigue under student shell. Styling entry: school-style jacket, overly calm eyes, old hairpin, and a stance that seems to have seen many eras. Motif: young appearance mismatched with old psychological time. Tension: soul age must outweigh youth signs, avoiding schoolgirl ambiguity. Visual evidence: old books, retro notes, restrained expression, and distance from peer environment. Boundary: avoid generic student or romance light novel.', eras: modernEras, tags: ['old_soul', 'student', 'reincarnation'] },
  { id: 'body_swap_actor', name: '换身演员', nameEn: 'Body-Swap Actor', group: 'J. 轮回 / 附身 / 借尸还魂', groupEn: 'J. Reincarnation / Possession / Returned Body', def: '第一识别是表演职业与真实换身经验纠缠的演员。造型入口：试镜服、镜前练习、身体动作和表情不匹配、像在确认这张脸可否使用的手。母题：职业表演遇到身份错位。张力：他不是普通演员，身体像临时角色服。视觉证据：化妆镜、角色卡、陌生手指、排练姿态断裂、看向镜中自己的怀疑。边界：避免普通明星或科幻变身特效。', defEn: 'First read: an actor whose profession and actual body-swap experience entangle. Styling entry: audition clothes, mirror rehearsal, mismatch between movement and expression, and hands checking whether this face can be used. Motif: professional performance meeting identity displacement. Tension: not a normal actor; the body feels like temporary role costume. Visual evidence: makeup mirror, role card, unfamiliar fingers, broken rehearsal posture, and suspicion toward mirror self. Boundary: avoid generic celebrity or sci-fi transformation effect.', eras: modernEras, tags: ['body_swap', 'actor', 'identity'] },
  { id: 'second_life_widow', name: '第二人生寡妇', nameEn: 'Second-Life Widow', group: 'J. 轮回 / 附身 / 借尸还魂', groupEn: 'J. Reincarnation / Possession / Returned Body', def: '第一识别是死后或重生后仍被前一段婚姻身份牵住的寡妇。造型入口：新身体或新装扮里的旧戒指、黑色细节、重新学习站姿和不敢完全庆祝的表情。母题：重生没有切断旧关系。张力：她不是普通寡妇，而是在第二人生里携带第一人生的礼仪负担。视觉证据：旧戒痕、半黑服制、整理新衣的手、复杂微笑。边界：避免普通再婚故事。', defEn: 'First read: a widow still held by a previous marriage after death or rebirth. Styling entry: old ring inside new body or outfit, black details, relearning posture, and an expression unwilling to fully celebrate. Motif: rebirth not severing old relation. Tension: she is not a normal widow but carries first-life etiquette burden inside a second life. Visual evidence: ring mark, half-black dress code, hands arranging new clothes, and complicated smile. Boundary: avoid ordinary remarriage story.', tags: ['second_life', 'widow', 'rebirth'] },
  { id: 'soul_rider_monk', name: '骑魂僧', nameEn: 'Soul-Rider Monk', group: 'J. 轮回 / 附身 / 借尸还魂', groupEn: 'J. Reincarnation / Possession / Returned Body', def: '第一识别是允许或控制灵魂临时进入身体的骑魂僧。造型入口：素袍、护符绳、闭眼站姿、肩背突然承重和像在让出身体控制权的手势。母题：修行变成身体借用技术。张力：不要写成夸张驱魔，重点是自愿交出身体与保持戒律的冲突。视觉证据：念珠、符绳、安静脸、身体微微后仰、旁人保持距离。边界：避免真实宗教冒犯或魔法战斗僧。', defEn: 'First read: a monk who permits or controls temporary soul entry into the body. Styling entry: plain robe, talisman cord, closed-eye stance, shoulders suddenly bearing weight, and a gesture yielding body control. Motif: practice becoming body-borrowing technique. Tension: avoid exaggerated exorcism; focus on conflict between voluntary surrender and discipline. Visual evidence: beads, cords, calm face, slight backward lean, and others keeping distance. Boundary: avoid real religious offense or battle monk.', tags: ['soul_rider', 'monk', 'possession'] },
  { id: 'wrong_body_prince', name: '错身王子', nameEn: 'Wrong-Body Prince', group: 'J. 轮回 / 附身 / 借尸还魂', groupEn: 'J. Reincarnation / Possession / Returned Body', def: '第一识别是王子灵魂落进不匹配身体后仍努力维持王室礼仪的人。造型入口：不合身礼服、错误身体比例、旧王室手势、困惑但克制的脸和像在校准新身体的站姿。母题：身份尊严与身体归属断裂。张力：他不是单纯变装，真正冲突在王室训练和陌生身体之间。视觉证据：过紧或过松衣领、戒指不合尺寸、手势精确但身体别扭、镜中确认。边界：避免普通王子或搞笑换身。', defEn: 'First read: a prince soul inside a mismatched body still trying to maintain royal etiquette. Styling entry: ill-fitting formalwear, wrong body proportion, old royal gestures, confused but restrained face, and a stance calibrating the new body. Motif: dignity split from bodily belonging. Tension: not simple cross-dressing; conflict lies between royal training and unfamiliar body. Visual evidence: too-tight or loose collar, ring wrong size, precise gesture but awkward body, and mirror checking. Boundary: avoid generic prince or comic body swap.', tags: ['wrong_body', 'prince', 'reincarnation'] }
];

export const CD_PERSONA_UNDEAD_CURSED: PersonaTerm[] = seeds.map(up);
